begin;

-- Adaptive Learning V3 extends the V2 guided journey with an explicit,
-- explainable knowledge graph.  It is additive: legacy learning rows remain
-- readable and V2 question sets keep their existing contract.

create table if not exists public.learning_canonical_subjects (
  id uuid primary key default extensions.uuid_generate_v4(),
  code text not null unique,
  name text not null,
  aliases text[] not null default '{}',
  capability text not null default 'OBJECTIVE_EVIDENCE_READY'
    check (capability in ('OBJECTIVE_EVIDENCE_READY', 'CONSTRUCTED_EVIDENCE_REQUIRED', 'OBSERVATIONAL_EVIDENCE_REQUIRED')),
  metadata jsonb not null default '{}'::jsonb,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.learning_curriculum_skills
  add column if not exists canonical_subject_id uuid references public.learning_canonical_subjects(id) on delete restrict;

alter table public.learning_question_bank
  add column if not exists canonical_subject_id uuid references public.learning_canonical_subjects(id) on delete set null,
  add column if not exists cognitive_process text,
  add column if not exists context_family text,
  add column if not exists knowledge_mapping_status text not null default 'LEGACY_UNMAPPED'
    check (knowledge_mapping_status in ('LEGACY_UNMAPPED', 'READY', 'BLOCKED')),
  add column if not exists knowledge_mapping_version text;

alter table public.learning_question_bank_skill_links
  drop constraint if exists learning_question_bank_skill_links_skill_role_check;
alter table public.learning_question_bank_skill_links
  add constraint learning_question_bank_skill_links_skill_role_check
    check (skill_role in ('PRIMARY', 'SUPPORTING', 'PREREQUISITE', 'TRANSFER'));
alter table public.learning_question_bank_skill_links
  add column if not exists evidence_bearing boolean not null default false,
  add column if not exists attribution_confidence numeric(4,3) not null default 1
    check (attribution_confidence between 0 and 1);

alter table public.learning_skill_evidence
  add column if not exists evidence_role text not null default 'PRIMARY'
    check (evidence_role in ('PRIMARY', 'SUPPORTING', 'PREREQUISITE', 'TRANSFER')),
  add column if not exists attribution_confidence numeric(4,3) not null default 1
    check (attribution_confidence between 0 and 1),
  add column if not exists question_bank_id uuid references public.learning_question_bank(id) on delete set null,
  add column if not exists misconception_tag_id uuid references public.learning_misconception_tags(id) on delete set null;

create table if not exists public.learning_skill_relationships (
  id uuid primary key default extensions.uuid_generate_v4(),
  from_canonical_skill_id uuid not null references public.learning_curriculum_skills(id) on delete cascade,
  to_canonical_skill_id uuid not null references public.learning_curriculum_skills(id) on delete cascade,
  relation_type text not null check (relation_type in ('PREREQUISITE', 'RELATED', 'TRANSFER')),
  relation_source text not null default 'TECESCOLA_DERIVED',
  confidence numeric(4,3) not null default 1 check (confidence between 0 and 1),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint learning_skill_relationships_not_self check (from_canonical_skill_id <> to_canonical_skill_id),
  unique (from_canonical_skill_id, to_canonical_skill_id, relation_type)
);
create index if not exists learning_skill_relationships_from_idx
  on public.learning_skill_relationships(from_canonical_skill_id, relation_type);
create index if not exists learning_skill_relationships_to_idx
  on public.learning_skill_relationships(to_canonical_skill_id, relation_type);

create table if not exists public.learning_question_option_misconceptions (
  id uuid primary key default extensions.uuid_generate_v4(),
  question_bank_id uuid not null references public.learning_question_bank(id) on delete cascade,
  option_value text not null,
  misconception_tag_id uuid not null references public.learning_misconception_tags(id) on delete cascade,
  canonical_skill_id uuid not null references public.learning_curriculum_skills(id) on delete restrict,
  confidence_weight numeric(4,3) not null default 1 check (confidence_weight between 0 and 1),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (question_bank_id, option_value, misconception_tag_id, canonical_skill_id)
);
create index if not exists learning_question_option_misconceptions_lookup_idx
  on public.learning_question_option_misconceptions(question_bank_id, option_value);

create table if not exists public.learning_evidence_attributions (
  id uuid primary key default extensions.uuid_generate_v4(),
  institution_id uuid not null references public.institutions(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  question_bank_id uuid not null references public.learning_question_bank(id) on delete restrict,
  guided_attempt_id uuid references public.learning_guided_step_attempts(id) on delete set null,
  canonical_skill_id uuid not null references public.learning_curriculum_skills(id) on delete restrict,
  evidence_role text not null check (evidence_role in ('PRIMARY', 'SUPPORTING', 'PREREQUISITE', 'TRANSFER')),
  correct boolean not null,
  score numeric(5,2) not null check (score between 0 and 100),
  attribution_confidence numeric(4,3) not null check (attribution_confidence between 0 and 1),
  misconception_tag_id uuid references public.learning_misconception_tags(id) on delete set null,
  purpose text check (purpose is null or purpose in ('PROBE', 'PRACTICE', 'TRANSFER', 'LOCK_IN', 'REVIEW')),
  context_family text,
  decision_reason_code text not null,
  created_at timestamptz not null default now(),
  unique (guided_attempt_id, question_bank_id, canonical_skill_id, evidence_role)
);
create index if not exists learning_evidence_attributions_student_skill_idx
  on public.learning_evidence_attributions(institution_id, student_id, canonical_skill_id, created_at desc);

create table if not exists public.learning_misconception_signals (
  id uuid primary key default extensions.uuid_generate_v4(),
  institution_id uuid not null references public.institutions(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  canonical_skill_id uuid not null references public.learning_curriculum_skills(id) on delete restrict,
  misconception_tag_id uuid not null references public.learning_misconception_tags(id) on delete cascade,
  state text not null default 'SIGNAL'
    check (state in ('SIGNAL', 'SUSPECTED', 'CONFIRMED', 'RECOVERING', 'RESOLVED')),
  signal_count integer not null default 0 check (signal_count >= 0),
  distinct_context_count integer not null default 0 check (distinct_context_count >= 0),
  recovery_count integer not null default 0 check (recovery_count >= 0),
  confidence numeric(4,3) not null default 0 check (confidence between 0 and 1),
  first_signal_at timestamptz,
  last_signal_at timestamptz,
  last_recovery_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  unique (institution_id, student_id, canonical_skill_id, misconception_tag_id)
);
create index if not exists learning_misconception_signals_student_idx
  on public.learning_misconception_signals(institution_id, student_id, state, updated_at desc);

alter table public.learning_guided_sessions
  add column if not exists original_target_canonical_subject_id uuid references public.learning_canonical_subjects(id) on delete set null,
  add column if not exists current_canonical_subject_id uuid references public.learning_canonical_subjects(id) on delete set null;

update public.learning_curriculum_skills skill
   set canonical_subject_id = subject.id
  from public.learning_canonical_subjects subject
 where skill.canonical_subject_id is null
   and (
     (skill.subject_area = 'MATEMATICA' and subject.code = 'MATHEMATICS')
     or (skill.subject_area = 'LINGUAGENS' and subject.code = 'PORTUGUESE')
   );

-- Canonical subject registry.  Aliases are intentionally explicit: an
-- ambiguous institutional label must be reviewed instead of silently guessed.
insert into public.learning_canonical_subjects(code, name, aliases, capability, metadata)
values
  ('PORTUGUESE', 'Lingua Portuguesa', array['Portugues', 'Lingua Portuguesa'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'READING_ARGUMENT')),
  ('MATHEMATICS', 'Matematica', array['Matematica'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'PERCENTAGE')),
  ('SCIENCE', 'Ciencias', array['Ciencias', 'Ciencias da Natureza'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'SCIENCE_TRANSFORMATIONS')),
  ('BIOLOGY', 'Biologia', array['Biologia'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'BIOLOGY_GENETICS')),
  ('PHYSICS', 'Fisica', array['Fisica'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'PHYSICS_AVERAGE_SPEED')),
  ('CHEMISTRY', 'Quimica', array['Quimica'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'CHEMISTRY_ATOMS')),
  ('HISTORY', 'Historia', array['Historia'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'HISTORY_INTERPRETATION')),
  ('GEOGRAPHY', 'Geografia', array['Geografia'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'GEOGRAPHY_TERRITORY')),
  ('PHILOSOPHY', 'Filosofia', array['Filosofia'], 'CONSTRUCTED_EVIDENCE_REQUIRED', jsonb_build_object('target_skill', 'PHILOSOPHY_ARGUMENT')),
  ('SOCIOLOGY', 'Sociologia', array['Sociologia'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'SOCIOLOGY_INSTITUTIONS')),
  ('ART', 'Arte', array['Arte'], 'CONSTRUCTED_EVIDENCE_REQUIRED', jsonb_build_object('target_skill', 'ART_INTERPRETATION')),
  ('PHYSICAL_EDUCATION', 'Educacao Fisica', array['Educacao Fisica', 'Ed. Fisica'], 'OBSERVATIONAL_EVIDENCE_REQUIRED', jsonb_build_object('target_skill', 'PE_SPORT_PRINCIPLES')),
  ('ENGLISH', 'Lingua Inglesa', array['Ingles', 'Lingua Inglesa'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'ENGLISH_READING')),
  ('RELIGIOUS_EDUCATION', 'Ensino Religioso', array['Ensino Religioso'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'RELIGIOUS_DIVERSITY')),
  ('COMPUTING', 'Computacao e Educacao Digital', array['Computacao', 'Educacao Digital'], 'OBJECTIVE_EVIDENCE_READY', jsonb_build_object('target_skill', 'COMPUTING_ALGORITHMS'))
on conflict (code) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  capability = excluded.capability,
  metadata = excluded.metadata,
  active = true,
  updated_at = now();

do $seed$
declare
  v_catalog_id uuid;
  v_expected_subject_codes text[] := array[
    'PORTUGUESE', 'MATHEMATICS', 'SCIENCE', 'BIOLOGY', 'PHYSICS',
    'CHEMISTRY', 'HISTORY', 'GEOGRAPHY', 'PHILOSOPHY', 'SOCIOLOGY',
    'ART', 'PHYSICAL_EDUCATION', 'ENGLISH', 'RELIGIOUS_EDUCATION', 'COMPUTING'
  ];
  v_expected_subject_count integer;
  v_expected_skill_count integer;
  v_expected_content_count integer := 0;
  v_materialized_question_count integer;
  v_question_set_item_count integer;
  subject_row record;
  skill_row record;
  skill_ids uuid[];
  target_row record;
  target_skill_id uuid;
  prerequisite_id uuid;
  question_id uuid;
  v_question_set_id uuid;
  question_number integer;
  purpose text;
  set_purpose text;
  context_family text;
  cognitive_process text;
  correct_text text;
  options jsonb;
  question_metadata jsonb;
  v3_question_pack jsonb;
  content_row record;
  mapping_row record;
  misconception_row record;
  tag_row record;
begin
  insert into public.learning_curriculum_catalogs(code, name, version, description, active)
  values ('TECESCOLA_CORE', 'TecEscola Core V3', '1.0', 'Catalogo autoral do grafo de conhecimento TecEscola.', true)
  on conflict (code, version) do update set name = excluded.name, description = excluded.description, active = true, updated_at = now()
  returning id into v_catalog_id;
  if v_catalog_id is null then
    select id into v_catalog_id from public.learning_curriculum_catalogs where code = 'TECESCOLA_CORE' and version = '1.0';
  end if;

  for skill_row in
    select * from jsonb_to_recordset(replace('[
      {"subject":"PORTUGUESE","code":"READING_LITERAL","title":"Compreensao literal","domain":"LEITURA","order":1},
      {"subject":"PORTUGUESE","code":"READING_INFERENCE","title":"Inferencia de leitura","domain":"LEITURA","order":2},
      {"subject":"PORTUGUESE","code":"READING_ARGUMENT","title":"Leitura argumentativa","domain":"ARGUMENTACAO","order":3},
      {"subject":"MATHEMATICS","code":"FRACTIONS","title":"Fundamentos de fracoes","domain":"NUMEROS","order":1},
      {"subject":"MATHEMATICS","code":"RATIO_PROPORTION","title":"Razao e proporcao","domain":"PROPORCOES","order":2},
      {"subject":"MATHEMATICS","code":"PERCENTAGE","title":"Porcentagem","domain":"NUMEROS","order":3},
      {"subject":"SCIENCE","code":"SCIENCE_MATTER","title":"Materia e propriedades","domain":"MATERIA","order":1},
      {"subject":"SCIENCE","code":"SCIENCE_TRANSFORMATIONS","title":"Transformacoes da materia","domain":"TRANSFORMACOES","order":2},
      {"subject":"SCIENCE","code":"SCIENCE_ENERGY","title":"Energia e suas formas","domain":"ENERGIA","order":3},
      {"subject":"BIOLOGY","code":"BIOLOGY_CELL","title":"Celula e organizacao da vida","domain":"CELULA","order":1},
      {"subject":"BIOLOGY","code":"BIOLOGY_GENETICS","title":"Fundamentos de genetica","domain":"GENETICA","order":2},
      {"subject":"BIOLOGY","code":"BIOLOGY_ECOLOGY","title":"Ecologia e interacoes","domain":"ECOLOGIA","order":3},
      {"subject":"PHYSICS","code":"PHYSICS_MEASUREMENT","title":"Medidas e unidades","domain":"MEDIDAS","order":1},
      {"subject":"PHYSICS","code":"PHYSICS_MOTION","title":"Movimento e representacoes","domain":"MOVIMENTO","order":2},
      {"subject":"PHYSICS","code":"PHYSICS_AVERAGE_SPEED","title":"Velocidade media","domain":"VELOCIDADE","order":3},
      {"subject":"CHEMISTRY","code":"CHEMISTRY_MATTER","title":"Materia e misturas","domain":"MATERIA","order":1},
      {"subject":"CHEMISTRY","code":"CHEMISTRY_ATOMS","title":"Atomos e modelos","domain":"ATOMOS","order":2},
      {"subject":"CHEMISTRY","code":"CHEMISTRY_TRANSFORMATIONS","title":"Transformacoes quimicas","domain":"TRANSFORMACOES","order":3},
      {"subject":"HISTORY","code":"HISTORY_SOURCES","title":"Fontes historicas","domain":"FONTES","order":1},
      {"subject":"HISTORY","code":"HISTORY_CHRONOLOGY","title":"Cronologia e periodizacao","domain":"CRONOLOGIA","order":2},
      {"subject":"HISTORY","code":"HISTORY_INTERPRETATION","title":"Interpretacao historica","domain":"INTERPRETACAO","order":3},
      {"subject":"GEOGRAPHY","code":"GEOGRAPHY_SPACE","title":"Espaco e lugar","domain":"ESPACO","order":1},
      {"subject":"GEOGRAPHY","code":"GEOGRAPHY_CARTOGRAPHY","title":"Cartografia e representacao","domain":"CARTOGRAFIA","order":2},
      {"subject":"GEOGRAPHY","code":"GEOGRAPHY_TERRITORY","title":"Territorio e paisagem","domain":"TERRITORIO","order":3},
      {"subject":"PHILOSOPHY","code":"PHILOSOPHY_CONCEPT","title":"Formacao de conceitos","domain":"CONCEITO","order":1},
      {"subject":"PHILOSOPHY","code":"PHILOSOPHY_ARGUMENT","title":"Argumentacao filosofica","domain":"ARGUMENTO","order":2},
      {"subject":"PHILOSOPHY","code":"PHILOSOPHY_LOGIC","title":"Analise logica","domain":"LOGICA","order":3},
      {"subject":"SOCIOLOGY","code":"SOCIOLOGY_INDIVIDUAL","title":"Individuo e sociedade","domain":"INDIVIDUO","order":1},
      {"subject":"SOCIOLOGY","code":"SOCIOLOGY_INSTITUTIONS","title":"Instituicoes sociais","domain":"INSTITUICOES","order":2},
      {"subject":"SOCIOLOGY","code":"SOCIOLOGY_STRUCTURE","title":"Estrutura social","domain":"ESTRUTURA","order":3},
      {"subject":"ART","code":"ART_ELEMENTS","title":"Elementos visuais","domain":"ELEMENTOS","order":1},
      {"subject":"ART","code":"ART_INTERPRETATION","title":"Interpretacao de obras","domain":"INTERPRETACAO","order":2},
      {"subject":"ART","code":"ART_CONTEXT","title":"Contexto artistico","domain":"CONTEXTO","order":3},
      {"subject":"PHYSICAL_EDUCATION","code":"PE_BODY_MOVEMENT","title":"Corpo e movimento","domain":"CORPO","order":1},
      {"subject":"PHYSICAL_EDUCATION","code":"PE_SPORT_PRINCIPLES","title":"Principios dos esportes","domain":"ESPORTES","order":2},
      {"subject":"PHYSICAL_EDUCATION","code":"PE_HEALTH_ACTIVITY","title":"Saude e atividade","domain":"SAUDE","order":3},
      {"subject":"ENGLISH","code":"ENGLISH_VOCABULARY","title":"Vocabulary in context","domain":"VOCABULARIO","order":1},
      {"subject":"ENGLISH","code":"ENGLISH_READING","title":"Literal reading","domain":"LEITURA","order":2},
      {"subject":"ENGLISH","code":"ENGLISH_INFERENCE","title":"Reading inference","domain":"INFERENCIA","order":3},
      {"subject":"RELIGIOUS_EDUCATION","code":"RELIGIOUS_TRADITIONS","title":"Tradicoes culturais","domain":"TRADICOES","order":1},
      {"subject":"RELIGIOUS_EDUCATION","code":"RELIGIOUS_DIVERSITY","title":"Diversidade e respeito","domain":"DIVERSIDADE","order":2},
      {"subject":"RELIGIOUS_EDUCATION","code":"RELIGIOUS_INTERPRETATION","title":"Interpretacao e dialogo","domain":"INTERPRETACAO","order":3},
      {"subject":"COMPUTING","code":"COMPUTING_ALGORITHMS","title":"Algoritmos e decomposicao","domain":"PENSAMENTO_COMPUTACIONAL","order":1},
      {"subject":"COMPUTING","code":"COMPUTING_DIGITAL_REPRESENTATION","title":"Representacao digital","domain":"MUNDO_DIGITAL","order":2},
      {"subject":"COMPUTING","code":"COMPUTING_DIGITAL_CITIZENSHIP","title":"Cidadania digital","domain":"CULTURA_DIGITAL","order":3}
    ]'::jsonb::text, '"order"', '"skill_order"')::jsonb) as item(subject text, code text, title text, domain text, skill_order integer)
  loop
    insert into public.learning_curriculum_skills(
      catalog_id, code, stage, grade_level, subject_area, domain, title, description,
      canonical_subject_id, active, metadata
    )
    select v_catalog_id, skill_row.code, 'ENSINO_MEDIO', 1, skill_row.subject,
      skill_row.domain, skill_row.title,
      'Skill canonica autoral TecEscola para o grafo V3.', subject.id, true,
      jsonb_build_object('v3_order', skill_row.skill_order, 'provenance', 'TECESCOLA_DERIVED')
      from public.learning_canonical_subjects subject
     where subject.code = skill_row.subject
    on conflict (catalog_id, code) do update set
      subject_area = excluded.subject_area,
      domain = excluded.domain,
      title = excluded.title,
      description = excluded.description,
      canonical_subject_id = excluded.canonical_subject_id,
      metadata = public.learning_curriculum_skills.metadata || excluded.metadata,
      active = true,
      updated_at = now();
  end loop;

  select count(*) into v_expected_subject_count
    from public.learning_canonical_subjects subject
   where subject.active and subject.code = any(v_expected_subject_codes);
  if v_expected_subject_count <> 15 then
    raise exception 'ADAPTIVE_V3_SKILL_REGISTRY_INCOMPLETE: expected 15 active canonical subjects, found %', v_expected_subject_count;
  end if;

  select count(*) into v_expected_skill_count
    from public.learning_curriculum_skills skill
    join public.learning_canonical_subjects subject on subject.id = skill.canonical_subject_id
   where skill.catalog_id = v_catalog_id
     and skill.active
     and subject.active
     and subject.code = any(v_expected_subject_codes);
  if v_expected_skill_count <> 45 then
    raise exception 'ADAPTIVE_V3_SKILL_REGISTRY_INCOMPLETE: expected 45 V3 canonical skills, found %', v_expected_skill_count;
  end if;

  for subject_row in
    select subject.code
      from public.learning_canonical_subjects subject
     where subject.active and subject.code = any(v_expected_subject_codes)
  loop
    select count(*) into v_expected_skill_count
      from public.learning_curriculum_skills skill
      join public.learning_canonical_subjects subject on subject.id = skill.canonical_subject_id
     where skill.catalog_id = v_catalog_id
       and skill.active
       and subject.code = subject_row.code;
    if v_expected_skill_count < 3 then
      raise exception 'ADAPTIVE_V3_SKILL_REGISTRY_INCOMPLETE: subject % has only % active skills', subject_row.code, v_expected_skill_count;
    end if;
  end loop;

  for subject_row in select * from public.learning_canonical_subjects where active loop
    select array_agg(skill.id order by (skill.metadata->>'v3_order')::integer)
      into skill_ids
      from public.learning_curriculum_skills skill
     where skill.catalog_id = v_catalog_id
       and skill.canonical_subject_id = subject_row.id
       and skill.active;
    if coalesce(array_length(skill_ids, 1), 0) >= 3 then
      insert into public.learning_skill_prerequisites(skill_id, prerequisite_skill_id)
      values (skill_ids[2], skill_ids[1]), (skill_ids[3], skill_ids[2])
      on conflict do nothing;
    end if;
    select skill.id into target_skill_id
      from public.learning_curriculum_skills skill
     where skill.catalog_id = v_catalog_id
       and skill.code = subject_row.metadata->>'target_skill'
       and skill.active;
    if target_skill_id is not null then
      insert into public.learning_curriculum_grade_targets(catalog_id, stage, grade_level, subject_area, canonical_skill_id, priority, sort_order, active)
      values (v_catalog_id, 'ENSINO_MEDIO', 1, subject_row.code, target_skill_id, 0, 0, true)
      on conflict (catalog_id, stage, grade_level, subject_area, canonical_skill_id)
      do update set active = true, updated_at = now();
      insert into public.learning_skill_lessons(canonical_skill_id, version, title, summary, content_markdown, worked_example, tips, estimated_minutes, metadata)
      values (
        target_skill_id, 3,
        (select title from public.learning_curriculum_skills where id = target_skill_id),
        'Vertical inicial do grafo de conhecimento V3.',
        'CONCEITO\n\nEste material apresenta uma ideia central e mostra como observar evidencias em contextos diferentes.\n\nEXEMPLO\n\nCompare a situacao com o conceito antes de escolher uma resposta.\n\nLIMITACAO\n\nUma resposta isolada nao confirma uma lacuna.',
        'Relacionar o contexto, a evidencia e o conceito antes de concluir.',
        array['Explique qual evidencia sustenta sua resposta.', 'Compare contextos diferentes antes de generalizar.'],
        8, jsonb_build_object('engine_version', 'V3', 'provenance', 'TECESCOLA_CORE_V3')
      ) on conflict (canonical_skill_id, version) do update set active = true, metadata = excluded.metadata, updated_at = now();
    end if;
  end loop;

  -- Existing V2 content becomes V3-ready only after it receives the explicit
  -- mapping fields; its IDs and authored text remain unchanged.
  update public.learning_question_bank question
     set canonical_subject_id = subject.id,
         cognitive_process = coalesce(question.metadata->>'cognitive_process', case question.metadata->>'adaptive_v2_purpose' when 'PROBE' then 'IDENTIFY' when 'PRACTICE' then 'APPLY' when 'TRANSFER' then 'INTERPRET' when 'LOCK_IN' then 'ANALYZE' else 'EVALUATE' end),
         context_family = coalesce(question.metadata->>'context_family', 'LEGACY_V2'),
         knowledge_mapping_status = 'READY',
         knowledge_mapping_version = 'V3',
         metadata = question.metadata || jsonb_build_object('knowledge_mapping_version', 'V3', 'knowledge_mapping_status', 'READY')
    from public.learning_canonical_subjects subject
   where question.source_type = 'TECESCOLA_CORE_V2'
     and subject.code = case when question.subject_area in ('MATEMATICA', 'MATHEMATICS') then 'MATHEMATICS' else 'PORTUGUESE' end;
  update public.learning_question_bank_skill_links link
     set evidence_bearing = true, attribution_confidence = 1
    from public.learning_question_bank question
   where question.id = link.question_bank_id
     and question.source_type = 'TECESCOLA_CORE_V2'
     and link.skill_role = 'PRIMARY';

  v3_question_pack := '[{"question_id":"v3-portuguese-reading_argument-1","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"editorial e tese","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"EDITORIAL_E_TESE","difficulty":"EASY","statement":"Um editorial defende a ampliacao de bibliotecas de bairro e apresenta dados de emprestimos. Qual e a tese central?","options":["Bibliotecas de bairro ampliam o acesso a leitura.","Todo livro deve ser digital.","Emprestimos substituem escolas.","Dados de emprestimos nao podem ser usados."],"correct_answer":"Bibliotecas de bairro ampliam o acesso a leitura.","explanation":"A tese e a ideia que o editorial procura sustentar com os dados.","secondary_links":[],"misconceptions":[{"option_value":"Todo livro deve ser digital.","tag_code":"THESIS_CONFUSED_WITH_DETAIL","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-2","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"noticia e fato","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"NOTICIA_E_FATO","difficulty":"EASY","statement":"Uma noticia informa que a escola abriu uma horta e cita data, local e numero de mudas. Qual trecho funciona como informacao verificavel?","options":["A horta foi aberta na segunda-feira.","A horta e a mais bonita da cidade.","Todos adoraram a iniciativa.","A medida vai mudar o mundo."],"correct_answer":"A horta foi aberta na segunda-feira.","explanation":"Data e local podem ser conferidos; os demais trechos sao avaliacao ou previsao.","secondary_links":[],"misconceptions":[{"option_value":"A horta e a mais bonita da cidade.","tag_code":"FACT_CONFUSED_WITH_OPINION","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-3","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"campanha de leitura","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"CAMPANHA_DE_LEITURA","difficulty":"EASY","statement":"Uma campanha apresenta o slogan Leia dez minutos por dia e uma imagem de estudantes lendo. Qual recurso reforca o argumento?","options":["O slogan transforma a proposta em uma acao concreta.","A imagem prova que todos gostam de ler.","O slogan elimina a necessidade de livros.","A imagem substitui os dados da campanha."],"correct_answer":"O slogan transforma a proposta em uma acao concreta.","explanation":"O slogan traduz a tese em uma pratica simples sem provar mais do que afirma.","secondary_links":[],"misconceptions":[{"option_value":"A imagem prova que todos gostam de ler.","tag_code":"SLOGAN_TREATED_AS_PROOF","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-4","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"carta de opiniao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"CARTA_DE_OPINIAO","difficulty":"MEDIUM","statement":"Na carta, Joana afirma que o recreio deve ter mais arvores porque a sombra reduz o calor. Qual evidencia apoia melhor a conclusao?","options":["Medidas de temperatura com e sem sombra.","A cor preferida dos estudantes.","O numero de cartazes no patio.","A opiniao de um estudante sobre musica."],"correct_answer":"Medidas de temperatura com e sem sombra.","explanation":"A evidencia mede diretamente a relacao entre sombra e temperatura.","secondary_links":[],"misconceptions":[{"option_value":"A cor preferida dos estudantes.","tag_code":"UNRELATED_EVIDENCE_USED","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-5","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"comparacao de fontes","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"COMPARACAO_DE_FONTES","difficulty":"MEDIUM","statement":"Duas fontes descrevem a mesma feira: uma e da organizacao e outra de um jornal. O que uma leitura critica deve fazer?","options":["Comparar perspectivas e evidencias das duas fontes.","Escolher a fonte mais curta.","Aceitar apenas a fonte com fotografia.","Somar todas as opinioes como fatos."],"correct_answer":"Comparar perspectivas e evidencias das duas fontes.","explanation":"Fontes podem ter finalidades diferentes; a comparacao ajuda a avaliar seus recortes.","secondary_links":[],"misconceptions":[{"option_value":"Escolher a fonte mais curta.","tag_code":"SOURCE_AUTHORITY_REPLACES_COMPARISON","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-6","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"inferencia no conto","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"INFERENCIA_NO_CONTO","difficulty":"MEDIUM","statement":"No conto, o personagem guarda o guarda-chuva mesmo com o ceu aberto e olha varias vezes para a janela. Que inferencia e sustentada?","options":["Ele espera uma mudanca no tempo ou alguem chegar.","Ele certamente perdeu a chave.","Ele nunca saiu de casa.","A janela esta quebrada."],"correct_answer":"Ele espera uma mudanca no tempo ou alguem chegar.","explanation":"A inferencia combina os sinais do comportamento sem afirmar uma causa que o texto nao apresenta.","secondary_links":[],"misconceptions":[{"option_value":"Ele certamente perdeu a chave.","tag_code":"INFERENCE_TREATED_AS_CERTAINTY","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-7","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"argumento e razao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"ARGUMENTO_E_RAZAO","difficulty":"MEDIUM","statement":"Uma proposta diz que o laboratorio deve abrir a tarde porque a procura por esse horario dobrou. Qual e a razao apresentada?","options":["O aumento da procura pelo horario da tarde.","A cor das paredes do laboratorio.","A existencia de outros laboratorios.","A preferencia do autor por ciencias."],"correct_answer":"O aumento da procura pelo horario da tarde.","explanation":"A razao e o dado usado para apoiar a proposta.","secondary_links":[],"misconceptions":[{"option_value":"A cor das paredes do laboratorio.","tag_code":"REASON_CONFUSED_WITH_PROPOSAL","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-8","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"contraponto","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"CONTRAPONTO","difficulty":"MEDIUM","statement":"Um texto defende uniformes, mas reconhece que algumas familias teriam custo inicial maior. Qual e a funcao desse trecho?","options":["Apresentar uma dificuldade e abrir espaco para resposta.","Provar que uniformes sao sempre baratos.","Mudar o assunto para transporte.","Encerrar o argumento sem justificativa."],"correct_answer":"Apresentar uma dificuldade e abrir espaco para resposta.","explanation":"O contraponto torna o argumento mais completo porque reconhece uma objecao.","secondary_links":[],"misconceptions":[{"option_value":"Provar que uniformes sao sempre baratos.","tag_code":"COUNTERARGUMENT_MISREAD","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-9","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"anuncio publico","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"ANUNCIO_PUBLICO","difficulty":"MEDIUM","statement":"Um aviso informa que a quadra ficara fechada na quarta para manutencao e indica outro local. Qual e a finalidade principal?","options":["Orientar a comunidade sobre uma mudanca de uso.","Narrar a historia da quadra.","Vender materiais esportivos.","Avaliar o desempenho dos alunos."],"correct_answer":"Orientar a comunidade sobre uma mudanca de uso.","explanation":"Avisos publicos organizam uma acao ou expectativa do leitor.","secondary_links":[],"misconceptions":[{"option_value":"Narrar a historia da quadra.","tag_code":"GENRE_PURPOSE_MISREAD","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-10","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"evidencia e conclusao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"EVIDENCIA_E_CONCLUSAO","difficulty":"MEDIUM","statement":"Uma pesquisa ouviu 80 alunos de uma turma sobre o horario de estudo. Qual conclusao e mais cuidadosa?","options":["Na turma pesquisada, a maioria prefere estudar no inicio da noite.","Todos os alunos da cidade preferem esse horario.","O horario causa melhores notas.","Nenhum aluno estuda pela manha."],"correct_answer":"Na turma pesquisada, a maioria prefere estudar no inicio da noite.","explanation":"A conclusao respeita a amostra e nao cria causalidade sem evidencia.","secondary_links":[],"misconceptions":[{"option_value":"Todos os alunos da cidade preferem esse horario.","tag_code":"SAMPLE_GENERALIZED","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-11","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"linguagem persuasiva","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"LINGUAGEM_PERSUASIVA","difficulty":"HARD","statement":"Um texto usa a expressao juntos podemos transformar o patio e apresenta etapas de plantio. O uso de juntos produz qual efeito?","options":["Convoca o leitor para uma acao coletiva.","Prova que o plantio ja terminou.","Indica que apenas gestores podem agir.","Substitui todas as etapas do plano."],"correct_answer":"Convoca o leitor para uma acao coletiva.","explanation":"A primeira pessoa do plural aproxima leitor e proposta, mas nao prova que a acao ocorreu.","secondary_links":[],"misconceptions":[{"option_value":"Prova que o plantio ja terminou.","tag_code":"PERSUASION_CONFUSED_WITH_EVIDENCE","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-portuguese-reading_argument-12","subject_code":"PORTUGUESE","target_skill":"READING_ARGUMENT","domain":"ARGUMENTACAO","topic":"sintese argumentativa","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"SINTESE_ARGUMENTATIVA","difficulty":"HARD","statement":"Um texto apresenta problema de descarte, dados de coleta e proposta de pontos de entrega. Qual sintese preserva sua linha argumentativa?","options":["A coleta melhora quando o problema e medido e a comunidade recebe uma alternativa.","O texto apenas descreve lixeiras coloridas.","A proposta elimina a necessidade de coleta.","Os dados mostram que todo descarte e ilegal."],"correct_answer":"A coleta melhora quando o problema e medido e a comunidade recebe uma alternativa.","explanation":"A sintese mantem problema, evidencia e proposta sem acrescentar uma acusacao.","secondary_links":[],"misconceptions":[{"option_value":"O texto apenas descreve lixeiras coloridas.","tag_code":"SUMMARY_ADDS_UNSUPPORTED_CLAIM","confidence_weight":0.8,"skill_code":"READING_ARGUMENT"}]},{"question_id":"v3-mathematics-percentage-1","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"desconto","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"DESCONTO","difficulty":"EASY","statement":"Uma mochila custa R$ 240 e recebe 25% de desconto. Qual e o valor do desconto?","options":["R$ 60","R$ 180","R$ 215","R$ 225"],"correct_answer":"R$ 60","explanation":"25% de 240 corresponde a R$ 60.","secondary_links":[],"misconceptions":[{"option_value":"R$ 180","tag_code":"DISCOUNT_CONFUSED_WITH_FINAL_PRICE","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-2","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"aumento","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"AUMENTO","difficulty":"EASY","statement":"Um ingresso de R$ 80 teve aumento de 15%. Qual e o novo preco?","options":["R$ 92","R$ 95","R$ 68","R$ 15"],"correct_answer":"R$ 92","explanation":"O aumento e R$ 12; somado a R$ 80, resulta em R$ 92.","secondary_links":[],"misconceptions":[{"option_value":"R$ 95","tag_code":"PERCENT_AS_ABSOLUTE_VALUE","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-3","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"parte e todo","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"PARTE_E_TODO","difficulty":"EASY","statement":"Em uma turma de 40 alunos, 30 entregaram a atividade. Qual percentual entregou?","options":["75%","30%","70%","133%"],"correct_answer":"75%","explanation":"30 dividido por 40 equivale a 75%.","secondary_links":[],"misconceptions":[{"option_value":"30%","tag_code":"PERCENT_DENOMINATOR_IGNORED","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-4","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"taxa equivalente","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"TAXA_EQUIVALENTE","difficulty":"MEDIUM","statement":"Uma taxa de 0,08 pode ser escrita como qual percentual?","options":["8%","0,8%","80%","0,08%"],"correct_answer":"8%","explanation":"Multiplicar 0,08 por 100 transforma a taxa em 8%.","secondary_links":[],"misconceptions":[{"option_value":"0,8%","tag_code":"DECIMAL_PERCENT_SHIFT","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-5","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"proporcao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"PROPORCAO","difficulty":"MEDIUM","statement":"Tres cadernos custam R$ 27. Mantendo o preco unitario, quanto custam cinco?","options":["R$ 45","R$ 30","R$ 54","R$ 90"],"correct_answer":"R$ 45","explanation":"Cada caderno custa R$ 9; cinco custam R$ 45.","secondary_links":[{"skillCode":"RATIO_PROPORTION","role":"SUPPORTING","evidenceBearing":true,"attributionConfidence":0.65}],"misconceptions":[{"option_value":"R$ 30","tag_code":"PROPORTION_NOT_SCALED","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-6","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"percentual acumulado","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"PERCENTUAL_ACUMULADO","difficulty":"MEDIUM","statement":"Uma assinatura de R$ 100 sobe 10% e depois recebe desconto de 10%. Qual valor final?","options":["R$ 99","R$ 100","R$ 90","R$ 110"],"correct_answer":"R$ 99","explanation":"Os percentuais incidem sobre bases diferentes: 110 vezes 0,9 = 99.","secondary_links":[],"misconceptions":[{"option_value":"R$ 100","tag_code":"SUCCESSIVE_PERCENTAGES_CANCELLED","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-7","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"fracao percentual","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"FRACAO_PERCENTUAL","difficulty":"MEDIUM","statement":"Qual fracao representa 40% de uma quantidade?","options":["2/5","4/5","1/4","40/1"],"correct_answer":"2/5","explanation":"40/100 simplifica para 2/5.","secondary_links":[],"misconceptions":[{"option_value":"4/5","tag_code":"PERCENT_NOT_SIMPLIFIED","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-8","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"grafico","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"GRAFICO","difficulty":"MEDIUM","statement":"Um grafico mostra 12 livros em abril e 18 em maio. Qual foi o aumento percentual?","options":["50%","6%","30%","150%"],"correct_answer":"50%","explanation":"O aumento foi 6 sobre a base 12: 50%.","secondary_links":[],"misconceptions":[{"option_value":"6%","tag_code":"INCREASE_USES_NEW_BASE","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-9","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"juros simples","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"JUROS_SIMPLES","difficulty":"MEDIUM","statement":"Uma aplicacao de R$ 500 rende 2% ao mes por um mes. Qual e o rendimento?","options":["R$ 10","R$ 20","R$ 502","R$ 100"],"correct_answer":"R$ 10","explanation":"2% de 500 e igual a R$ 10.","secondary_links":[],"misconceptions":[{"option_value":"R$ 20","tag_code":"RATE_TREATED_AS_AMOUNT","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-10","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"pesquisa","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PESQUISA","difficulty":"MEDIUM","statement":"Em uma pesquisa, 18 de 60 pessoas escolheram a opcao A. Qual percentual isso representa?","options":["30%","18%","42%","60%"],"correct_answer":"30%","explanation":"18 dividido por 60 resulta em 30%.","secondary_links":[],"misconceptions":[{"option_value":"18%","tag_code":"PART_WHOLE_REVERSED","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-11","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"comissao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"COMISSAO","difficulty":"HARD","statement":"Uma venda de R$ 1.200 gera comissao de 5%. Qual comissao sera paga?","options":["R$ 60","R$ 240","R$ 1.140","R$ 5"],"correct_answer":"R$ 60","explanation":"0,05 vezes 1.200 = 60.","secondary_links":[],"misconceptions":[{"option_value":"R$ 240","tag_code":"COMMISSION_RATE_MISREAD","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-mathematics-percentage-12","subject_code":"MATHEMATICS","target_skill":"PERCENTAGE","domain":"NUMEROS","topic":"ofertas","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"OFERTAS","difficulty":"HARD","statement":"Oferta A da 20% de desconto em R$ 150; oferta B tira R$ 25. Qual oferece maior desconto?","options":["Oferta A, com R$ 30.","Oferta B, com R$ 25.","As duas, com R$ 20.","Oferta B, com R$ 30."],"correct_answer":"Oferta A, com R$ 30.","explanation":"20% de 150 e R$ 30, maior que R$ 25.","secondary_links":[],"misconceptions":[{"option_value":"Oferta B, com R$ 25.","tag_code":"PERCENT_COMPARED_WITHOUT_BASE","confidence_weight":0.8,"skill_code":"PERCENTAGE"}]},{"question_id":"v3-science-science_transformations-1","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"fusao","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"FUSAO","difficulty":"EASY","statement":"Cubos de gelo deixados sobre a mesa viram agua liquida. Que transformacao ocorreu?","options":["Fusao","Evaporacao","Condensacao","Solidificacao"],"correct_answer":"Fusao","explanation":"Fusao e a passagem do solido para o liquido.","secondary_links":[],"misconceptions":[{"option_value":"Evaporacao","tag_code":"STATE_CHANGE_DIRECTION_CONFUSED","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-2","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"combustao","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"COMBUSTAO","difficulty":"EASY","statement":"Uma vela acesa produz luz, calor e novos gases. Por que isso e uma transformacao quimica?","options":["Novas substancias sao formadas.","A cera apenas muda de lugar.","A vela fica mais fria.","O pavio se torna agua."],"correct_answer":"Novas substancias sao formadas.","explanation":"A combustao altera a composicao e forma gases.","secondary_links":[],"misconceptions":[{"option_value":"A cera apenas muda de lugar.","tag_code":"CHEMICAL_CHANGE_CONFUSED_WITH_SHAPE","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-3","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"ciclo da agua","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"CICLO_DA_AGUA","difficulty":"EASY","statement":"A agua de uma poca desaparece em um dia quente. Qual processo explica a mudanca?","options":["Evaporacao","Fusao","Precipitacao","Congelamento"],"correct_answer":"Evaporacao","explanation":"O calor favorece a passagem do liquido para vapor.","secondary_links":[],"misconceptions":[{"option_value":"Fusao","tag_code":"EVAPORATION_CONFUSED_WITH_BOILING","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-4","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"mistura","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"MISTURA","difficulty":"MEDIUM","statement":"Agua e areia foram colocadas em um copo. Qual metodo separa melhor os componentes?","options":["Filtracao","Fusao","Combustao","Imantacao"],"correct_answer":"Filtracao","explanation":"A areia fica retida no filtro enquanto a agua atravessa.","secondary_links":[],"misconceptions":[{"option_value":"Fusao","tag_code":"SEPARATION_METHOD_MISREAD","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-5","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"conducao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"CONDUCAO","difficulty":"MEDIUM","statement":"Uma colher metalica esquenta dentro da sopa. Como o calor chegou a sua ponta?","options":["Por conducao pelo metal.","Por fotossintese.","Por evaporacao da colher.","Por separacao magnetica."],"correct_answer":"Por conducao pelo metal.","explanation":"O metal conduz energia termica ao longo do objeto.","secondary_links":[],"misconceptions":[{"option_value":"Por fotossintese.","tag_code":"HEAT_TRANSFER_CONFUSED","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-6","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"mudanca fisica","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"MUDANCA_FISICA","difficulty":"MEDIUM","statement":"Uma folha de papel foi dobrada e depois desdobrada. Por que a mudanca e fisica?","options":["A composicao do papel permanece a mesma.","Surge uma nova substancia.","O papel vira liquido.","A dobradura libera oxigenio."],"correct_answer":"A composicao do papel permanece a mesma.","explanation":"A forma muda, mas a substancia continua sendo papel.","secondary_links":[],"misconceptions":[{"option_value":"Surge uma nova substancia.","tag_code":"PHYSICAL_CHANGE_CONFUSED_WITH_CHEMICAL","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-7","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"densidade","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"DENSIDADE","difficulty":"MEDIUM","statement":"Dois blocos de mesmo volume: um pesa mais que o outro. O que se pode inferir?","options":["O mais pesado tem maior densidade.","O mais leve tem maior densidade.","Eles tem necessariamente a mesma massa.","Volume nao participa da densidade."],"correct_answer":"O mais pesado tem maior densidade.","explanation":"Com volumes iguais, maior massa implica maior densidade.","secondary_links":[],"misconceptions":[{"option_value":"O mais leve tem maior densidade.","tag_code":"DENSITY_IGNORES_MASS","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-8","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"experimento","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"EXPERIMENTO","difficulty":"MEDIUM","statement":"Uma planta ficou em local claro e outra no escuro, com a mesma agua. O que a comparacao investiga?","options":["Efeito da luz sobre o crescimento.","Efeito da agua sobre o metal.","A massa do vaso.","A temperatura de uma estrela."],"correct_answer":"Efeito da luz sobre o crescimento.","explanation":"Manter a agua igual destaca a variavel luz.","secondary_links":[],"misconceptions":[{"option_value":"Efeito da agua sobre o metal.","tag_code":"CONTROL_VARIABLE_IGNORED","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-9","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"oxidacao","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"OXIDACAO","difficulty":"MEDIUM","statement":"Um portao de ferro exposto a chuva enferruja. Qual condicao favorece o processo?","options":["Contato com agua e oxigenio.","Ausencia completa de ar.","Congelamento imediato.","Filtracao da tinta."],"correct_answer":"Contato com agua e oxigenio.","explanation":"A ferrugem resulta da reacao do ferro com oxigenio e agua.","secondary_links":[],"misconceptions":[{"option_value":"Ausencia completa de ar.","tag_code":"OXIDATION_CAUSE_MISREAD","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-10","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"pressao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PRESSAO","difficulty":"MEDIUM","statement":"Ao apertar uma seringa tampada, o ar oferece resistencia. Qual explicacao e adequada?","options":["As particulas do ar ocupam espaco e colidem.","O ar nao tem particulas.","A seringa produz agua.","A pressao desaparece ao reduzir o volume."],"correct_answer":"As particulas do ar ocupam espaco e colidem.","explanation":"O modelo particulado explica a resistencia.","secondary_links":[],"misconceptions":[{"option_value":"O ar nao tem particulas.","tag_code":"PARTICLE_MODEL_DENIED","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-11","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"reciclagem","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"RECICLAGEM","difficulty":"HARD","statement":"Separar vidro, papel e metal antes da coleta facilita qual etapa?","options":["Reaproveitamento de materiais.","Evaporacao da agua.","Formacao de combustivel fossil.","Aumento da mistura."],"correct_answer":"Reaproveitamento de materiais.","explanation":"A separacao reduz contaminacao e facilita a reciclagem.","secondary_links":[],"misconceptions":[{"option_value":"Evaporacao da agua.","tag_code":"RECYCLING_GOAL_MISREAD","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-science-science_transformations-12","subject_code":"SCIENCE","target_skill":"SCIENCE_TRANSFORMATIONS","domain":"TRANSFORMACOES","topic":"conversao de energia","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"CONVERSAO_DE_ENERGIA","difficulty":"HARD","statement":"Uma placa solar transforma luz em energia eletrica. O que muda principalmente?","options":["A forma de energia disponivel.","O material vira agua.","A luz deixa de existir.","A eletricidade vira massa."],"correct_answer":"A forma de energia disponivel.","explanation":"O dispositivo converte energia luminosa em eletrica.","secondary_links":[],"misconceptions":[{"option_value":"O material vira agua.","tag_code":"ENERGY_CONVERSION_DENIED","confidence_weight":0.8,"skill_code":"SCIENCE_TRANSFORMATIONS"}]},{"question_id":"v3-biology-biology_genetics-1","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"alelo","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"ALELO","difficulty":"EASY","statement":"Em uma familia, diferentes alelos influenciam a cor dos olhos. O que e um alelo?","options":["Uma versao de um gene.","Uma celula inteira.","Um orgao do corpo.","Uma especie diferente."],"correct_answer":"Uma versao de um gene.","explanation":"Alelo e uma forma alternativa de um gene.","secondary_links":[],"misconceptions":[{"option_value":"Uma celula inteira.","tag_code":"ALLELE_CONFUSED_WITH_CELL","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-2","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"hereditariedade","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"HEREDITARIEDADE","difficulty":"EASY","statement":"Pais com uma caracteristica podem ter filho sem ela. Qual explicacao e possivel?","options":["O filho recebeu outra combinacao de alelos.","Caracteristicas nunca dependem de genes.","Todos os filhos sao geneticamente identicos.","O ambiente altera todo o DNA dos pais."],"correct_answer":"O filho recebeu outra combinacao de alelos.","explanation":"A combinacao herdada pode diferir entre irmaos.","secondary_links":[],"misconceptions":[{"option_value":"Caracteristicas nunca dependem de genes.","tag_code":"INHERITANCE_TREATED_AS_COPY","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-3","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"dominancia","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"DOMINANCIA","difficulty":"EASY","statement":"Em um modelo, A domina a. Um individuo Aa apresenta qual alelo no fenotipo?","options":["A","a apenas","Nenhum alelo","AA e aa ao mesmo tempo"],"correct_answer":"A","explanation":"No modelo dado, o alelo dominante se expressa em Aa.","secondary_links":[],"misconceptions":[{"option_value":"a apenas","tag_code":"DOMINANCE_REVERSED","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-4","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"probabilidade","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"PROBABILIDADE","difficulty":"MEDIUM","statement":"No cruzamento Aa x Aa, usando dominancia completa, qual proporcao esperada de aa?","options":["25%","50%","75%","100%"],"correct_answer":"25%","explanation":"As combinacoes incluem um aa em quatro.","secondary_links":[],"misconceptions":[{"option_value":"50%","tag_code":"PUNNETT_COUNT_MISREAD","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-5","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"mutacao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"MUTACAO","difficulty":"MEDIUM","statement":"Uma mudanca no DNA pode nao alterar uma caracteristica observavel. Por que?","options":["Pode ocorrer em regiao sem efeito ou ser compensada.","Toda mudanca no DNA e fatal.","DNA nao participa das caracteristicas.","A mutacao sempre altera o ambiente."],"correct_answer":"Pode ocorrer em regiao sem efeito ou ser compensada.","explanation":"O efeito depende do gene, da regiao e do contexto.","secondary_links":[],"misconceptions":[{"option_value":"Toda mudanca no DNA e fatal.","tag_code":"MUTATION_ALWAYS_VISIBLE","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-6","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"selecao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"SELECAO","difficulty":"MEDIUM","statement":"Uma populacao de insetos passa a ter mais individuos resistentes ao pesticida apos varias geracoes. Qual processo explica?","options":["Selecao de variantes resistentes.","Treino individual dos insetos.","Mudanca instantanea em todos os genes.","Eliminacao da hereditariedade."],"correct_answer":"Selecao de variantes resistentes.","explanation":"O pesticida favorece a sobrevivencia e reproducao de variantes resistentes.","secondary_links":[],"misconceptions":[{"option_value":"Treino individual dos insetos.","tag_code":"SELECTION_CONFUSED_WITH_TRAINING","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-7","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"cromossomo","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"CROMOSSOMO","difficulty":"MEDIUM","statement":"Onde esta a maior parte do material genetico de uma celula animal?","options":["No nucleo.","Na parede celular.","No vacuolo de agua.","No espaco extracelular."],"correct_answer":"No nucleo.","explanation":"O nucleo abriga os cromossomos na maioria das celulas animais.","secondary_links":[],"misconceptions":[{"option_value":"Na parede celular.","tag_code":"CELL_STRUCTURE_MISPLACED","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-8","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"DNA e RNA","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"DNA_E_RNA","difficulty":"MEDIUM","statement":"Qual diferenca geral entre DNA e RNA e correta?","options":["O RNA costuma participar da leitura da informacao genetica.","O DNA existe apenas fora das celulas.","RNA nao possui nucleotideos.","DNA e sempre uma proteina."],"correct_answer":"O RNA costuma participar da leitura da informacao genetica.","explanation":"DNA armazena informacao e RNA atua em sua expressao.","secondary_links":[],"misconceptions":[{"option_value":"O DNA existe apenas fora das celulas.","tag_code":"DNA_RNA_FUNCTIONS_SWAPPED","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-9","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"caracteristica complexa","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"CARACTERISTICA_COMPLEXA","difficulty":"MEDIUM","statement":"Altura humana varia de forma continua. Qual ideia explica melhor?","options":["Muitos genes e ambiente podem contribuir.","Apenas um alelo determina toda altura.","Ambiente nunca afeta fenotipo.","Altura nao tem relacao com heranca."],"correct_answer":"Muitos genes e ambiente podem contribuir.","explanation":"Caracteristicas complexas resultam de varios fatores.","secondary_links":[],"misconceptions":[{"option_value":"Apenas um alelo determina toda altura.","tag_code":"COMPLEX_TRAIT_SINGLE_CAUSE","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-10","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"fenotipo","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"FENOTIPO","difficulty":"MEDIUM","statement":"Duas plantas com genotipos iguais crescem com alturas diferentes em ambientes distintos. O que isso mostra?","options":["Fenotipo resulta da interacao entre genes e ambiente.","Genotipo muda a cada rega.","Ambiente nao interfere.","Fenotipo e sempre identico ao genotipo."],"correct_answer":"Fenotipo resulta da interacao entre genes e ambiente.","explanation":"A expressao observada depende de fatores geneticos e ambientais.","secondary_links":[],"misconceptions":[{"option_value":"Genotipo muda a cada rega.","tag_code":"GENOTYPE_EQUALS_PHENOTYPE","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-11","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"heranca ligada ao X","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"HERANCA_LIGADA_AO_X","difficulty":"HARD","statement":"Uma caracteristica ligada ao cromossomo X pode aparecer mais em homens em certo modelo. Qual razao?","options":["Homens possuem uma unica copia de X.","Homens nao possuem cromossomos.","Mulheres sempre expressam todos os alelos.","O cromossomo Y e uma copia de X."],"correct_answer":"Homens possuem uma unica copia de X.","explanation":"Uma unica copia pode revelar um alelo recessivo ligado ao X.","secondary_links":[],"misconceptions":[{"option_value":"Homens nao possuem cromossomos.","tag_code":"SEX_LINKAGE_REVERSED","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-biology-biology_genetics-12","subject_code":"BIOLOGY","target_skill":"BIOLOGY_GENETICS","domain":"GENETICA","topic":"diversidade genetica","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"DIVERSIDADE_GENETICA","difficulty":"HARD","statement":"Por que a diversidade genetica ajuda uma populacao diante de uma doenca?","options":["Aumenta a chance de existirem variantes resistentes.","Faz todos os individuos iguais.","Elimina a selecao natural.","Impede qualquer mutacao."],"correct_answer":"Aumenta a chance de existirem variantes resistentes.","explanation":"Variacao amplia as possibilidades de resposta da populacao.","secondary_links":[],"misconceptions":[{"option_value":"Faz todos os individuos iguais.","tag_code":"DIVERSITY_REDUCES_SURVIVAL","confidence_weight":0.8,"skill_code":"BIOLOGY_GENETICS"}]},{"question_id":"v3-physics-physics_average_speed-1","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"velocidade media","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"VELOCIDADE_MEDIA","difficulty":"EASY","statement":"Um carro percorre 120 km em 2 h. Qual e sua velocidade media?","options":["60 km/h","240 km/h","118 km/h","2 km/h"],"correct_answer":"60 km/h","explanation":"Velocidade media e distancia dividida pelo tempo: 120/2 = 60 km/h.","secondary_links":[{"skillCode":"RATIO_PROPORTION","role":"SUPPORTING","evidenceBearing":true,"attributionConfidence":0.65}],"misconceptions":[{"option_value":"240 km/h","tag_code":"SPEED_MULTIPLIES_DISTANCE_TIME","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-2","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"unidades","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"UNIDADES","difficulty":"EASY","statement":"Uma bicicleta percorre 300 m em 60 s. Qual e a velocidade media em m/s?","options":["5 m/s","18 m/s","360 m/s","0,2 m/s"],"correct_answer":"5 m/s","explanation":"300 dividido por 60 resulta em 5 m/s.","secondary_links":[{"skillCode":"RATIO_PROPORTION","role":"SUPPORTING","evidenceBearing":true,"attributionConfidence":0.65}],"misconceptions":[{"option_value":"18 m/s","tag_code":"SPEED_UNIT_CONVERSION","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-3","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"distancia","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"DISTANCIA","difficulty":"EASY","statement":"Um trem viaja a 80 km/h durante 3 h. Que distancia percorre?","options":["240 km","83 km","26,7 km","80 km"],"correct_answer":"240 km","explanation":"Distancia e velocidade vezes tempo: 80 x 3 = 240 km.","secondary_links":[{"skillCode":"RATIO_PROPORTION","role":"SUPPORTING","evidenceBearing":true,"attributionConfidence":0.65}],"misconceptions":[{"option_value":"83 km","tag_code":"DISTANCE_DIVIDED_INSTEAD_OF_MULTIPLIED","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-4","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"tempo","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"TEMPO","difficulty":"MEDIUM","statement":"Uma viagem de 150 km ocorre a 50 km/h. Quanto tempo dura?","options":["3 h","100 h","200 h","0,33 h"],"correct_answer":"3 h","explanation":"Tempo e distancia dividida pela velocidade: 150/50 = 3 h.","secondary_links":[{"skillCode":"RATIO_PROPORTION","role":"PREREQUISITE","evidenceBearing":true,"attributionConfidence":0.35}],"misconceptions":[{"option_value":"100 h","tag_code":"TIME_MULTIPLIES_SPEED_DISTANCE","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-5","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"grafico posicao-tempo","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"GRAFICO_POSICAO_TEMPO","difficulty":"MEDIUM","statement":"Em um grafico posicao-tempo, uma reta mais inclinada indica maior:","options":["Velocidade","Massa","Temperatura","Tempo total parado"],"correct_answer":"Velocidade","explanation":"A inclinacao representa a variacao da posicao por tempo.","secondary_links":[],"misconceptions":[{"option_value":"Massa","tag_code":"GRAPH_SLOPE_MISREAD","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-6","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"movimento uniforme","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"MOVIMENTO_UNIFORME","difficulty":"MEDIUM","statement":"Um objeto percorre distancias iguais em tempos iguais. Como e classificado o movimento?","options":["Uniforme","Circular necessariamente","Aleatorio","Sem movimento"],"correct_answer":"Uniforme","explanation":"A regularidade da razao distancia-tempo caracteriza movimento uniforme.","secondary_links":[],"misconceptions":[{"option_value":"Circular necessariamente","tag_code":"UNIFORM_MOTION_DENIED","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-7","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"encontro","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"ENCONTRO","difficulty":"MEDIUM","statement":"Dois ciclistas saem de pontos separados por 30 km, com velocidades de 10 e 5 km/h em direcao um ao outro. Em quanto tempo se encontram?","options":["2 h","3 h","6 h","15 h"],"correct_answer":"2 h","explanation":"A velocidade relativa e 15 km/h; 30/15 = 2 h.","secondary_links":[{"skillCode":"RATIO_PROPORTION","role":"SUPPORTING","evidenceBearing":true,"attributionConfidence":0.65}],"misconceptions":[{"option_value":"3 h","tag_code":"RELATIVE_SPEED_IGNORED","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-8","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"media de trechos","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"MEDIA_DE_TRECHOS","difficulty":"MEDIUM","statement":"Um estudante caminha 2 km em 30 min e depois 1 km em 30 min. Qual velocidade media total em km/h?","options":["3 km/h","2 km/h","1 km/h","6 km/h"],"correct_answer":"3 km/h","explanation":"Sao 3 km em 1 h, portanto 3 km/h.","secondary_links":[],"misconceptions":[{"option_value":"2 km/h","tag_code":"AVERAGE_USES_AVERAGE_SPEEDS","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-9","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"conversao","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"CONVERSAO","difficulty":"MEDIUM","statement":"Uma velocidade de 72 km/h equivale a quantos m/s?","options":["20 m/s","7,2 m/s","72 m/s","259,2 m/s"],"correct_answer":"20 m/s","explanation":"Dividir por 3,6 converte km/h para m/s.","secondary_links":[],"misconceptions":[{"option_value":"7,2 m/s","tag_code":"KMH_MS_CONVERSION","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-10","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"area no grafico","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"AREA_NO_GRAFICO","difficulty":"MEDIUM","statement":"A area sob um grafico velocidade-tempo representa qual grandeza?","options":["Deslocamento","Massa","Aceleracao","Temperatura"],"correct_answer":"Deslocamento","explanation":"A area soma velocidade ao longo do tempo.","secondary_links":[],"misconceptions":[{"option_value":"Massa","tag_code":"GRAPH_AREA_MISREAD","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-11","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"aceleracao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"ACELERACAO","difficulty":"HARD","statement":"Um carro passa de 10 para 20 m/s em 5 s. Qual aceleracao media?","options":["2 m/s2","10 m/s2","30 m/s2","0,5 m/s2"],"correct_answer":"2 m/s2","explanation":"Aceleracao media e variacao de velocidade por tempo: 10/5 = 2 m/s2.","secondary_links":[],"misconceptions":[{"option_value":"10 m/s2","tag_code":"ACCELERATION_NOT_DIVIDED","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-physics-physics_average_speed-12","subject_code":"PHYSICS","target_skill":"PHYSICS_AVERAGE_SPEED","domain":"VELOCIDADE","topic":"comparacao","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"COMPARACAO","difficulty":"HARD","statement":"Dois trajetos tem a mesma distancia, mas um leva mais tempo. Qual trajeto tem menor velocidade media?","options":["O que leva mais tempo.","O que leva menos tempo.","Os dois sempre tem a mesma.","Nenhum pode ser comparado."],"correct_answer":"O que leva mais tempo.","explanation":"Com a mesma distancia, maior tempo reduz a razao distancia-tempo.","secondary_links":[],"misconceptions":[{"option_value":"O que leva menos tempo.","tag_code":"SAME_DISTANCE_SAME_SPEED","confidence_weight":0.8,"skill_code":"PHYSICS_AVERAGE_SPEED"}]},{"question_id":"v3-chemistry-chemistry_atoms-1","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"nucleo","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"NUCLEO","difficulty":"EASY","statement":"No modelo atual, o atomo possui nucleo e eletrosfera. Onde ficam proton e neutron?","options":["No nucleo.","Na eletrosfera.","Fora do atomo.","Somente na ligacao."],"correct_answer":"No nucleo.","explanation":"Protons e neutrons formam o nucleo atomico.","secondary_links":[],"misconceptions":[{"option_value":"Na eletrosfera.","tag_code":"NUCLEUS_SHELL_SWAPPED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-2","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"numero atomico","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"NUMERO_ATOMICO","difficulty":"EASY","statement":"Um atomo com numero atomico 8 possui quantos protons?","options":["8","16","4","0"],"correct_answer":"8","explanation":"O numero atomico identifica a quantidade de protons.","secondary_links":[],"misconceptions":[{"option_value":"16","tag_code":"ATOMIC_NUMBER_DOUBLED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-3","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"ion","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"ION","difficulty":"EASY","statement":"Quando um atomo neutro perde um eletron, ele se torna:","options":["Um cation.","Um anion.","Um neutron.","Uma molecula neutra sempre."],"correct_answer":"Um cation.","explanation":"Perder carga negativa deixa excesso relativo de carga positiva.","secondary_links":[],"misconceptions":[{"option_value":"Um anion.","tag_code":"ION_CHARGE_REVERSED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-4","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"isotopos","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"ISOTOPOS","difficulty":"MEDIUM","statement":"Dois atomos com mesmo numero de protons e diferente numero de neutrons sao:","options":["Isotopos.","Ions de cargas opostas.","Moleculas.","Elementos diferentes."],"correct_answer":"Isotopos.","explanation":"Isotopos pertencem ao mesmo elemento e diferem no numero de neutrons.","secondary_links":[],"misconceptions":[{"option_value":"Ions de cargas opostas.","tag_code":"ISOTOPE_CONFUSED_WITH_ION","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-5","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"ligacao ionica","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"LIGACAO_IONICA","difficulty":"MEDIUM","statement":"Na formacao de cloreto de sodio, ocorre transferencia de eletron. Que tipo de ligacao se forma?","options":["Ionica.","Metalica apenas.","Ponte de hidrogenio.","Nenhuma."],"correct_answer":"Ionica.","explanation":"A transferencia gera ions atraidos eletrostaticamente.","secondary_links":[],"misconceptions":[{"option_value":"Metalica apenas.","tag_code":"IONIC_BOND_MISNAMED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-6","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"ligacao covalente","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"LIGACAO_COVALENTE","difficulty":"MEDIUM","statement":"Na molecula de agua, os atomos compartilham eletrons. Isso caracteriza ligacao:","options":["Covalente.","Ionica por transferencia total.","Metalica.","Nuclear."],"correct_answer":"Covalente.","explanation":"Compartilhar pares de eletrons e caracteristico da ligacao covalente.","secondary_links":[],"misconceptions":[{"option_value":"Ionica por transferencia total.","tag_code":"COVALENT_SHARING_DENIED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-7","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"conservacao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"CONSERVACAO","difficulty":"MEDIUM","statement":"Na reacao 2H2 + O2 -> 2H2O, o que se conserva?","options":["A quantidade de atomos de cada elemento.","O numero de moleculas sempre.","A temperatura.","A cor dos reagentes."],"correct_answer":"A quantidade de atomos de cada elemento.","explanation":"A equacao balanceada conserva atomos de hidrogenio e oxigenio.","secondary_links":[],"misconceptions":[{"option_value":"O numero de moleculas sempre.","tag_code":"REACTION_CONSERVES_MOLECULES","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-8","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"pH","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"PH","difficulty":"MEDIUM","statement":"Uma solucao com pH 3 e classificada como:","options":["Acida.","Basica.","Neutra.","Sem agua necessariamente."],"correct_answer":"Acida.","explanation":"Valores menores que 7 indicam acidez em agua.","secondary_links":[],"misconceptions":[{"option_value":"Basica.","tag_code":"PH_SCALE_REVERSED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-9","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"solubilidade","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"SOLUBILIDADE","difficulty":"MEDIUM","statement":"Ao aquecer a agua, certo soluto passa a dissolver mais. O que aumenta?","options":["A solubilidade desse soluto.","A massa do soluto sem adicionar nada.","O numero atomico.","A carga do copo."],"correct_answer":"A solubilidade desse soluto.","explanation":"Solubilidade indica quanto soluto se dissolve em uma condicao.","secondary_links":[],"misconceptions":[{"option_value":"A massa do soluto sem adicionar nada.","tag_code":"SOLUBILITY_CONFUSED_WITH_MASS","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-10","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"separacao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"SEPARACAO","difficulty":"MEDIUM","statement":"Uma mistura de agua e sal pode ser separada por evaporacao porque:","options":["A agua muda para vapor e o sal permanece.","O sal vira gas primeiro.","A agua se transforma em sal.","Os atomos desaparecem."],"correct_answer":"A agua muda para vapor e o sal permanece.","explanation":"A diferenca de volatilidade permite recuperar o sal.","secondary_links":[],"misconceptions":[{"option_value":"O sal vira gas primeiro.","tag_code":"EVAPORATION_REMOVES_SOLUTE","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-11","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"reacao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"REACAO","difficulty":"HARD","statement":"Bolhas surgem ao misturar duas substancias e o recipiente esquenta. Esses sinais sugerem:","options":["Reacao quimica.","Apenas mudanca de forma.","Separacao mecanica.","Congelamento."],"correct_answer":"Reacao quimica.","explanation":"Gas e variacao de temperatura podem indicar novas substancias.","secondary_links":[],"misconceptions":[{"option_value":"Apenas mudanca de forma.","tag_code":"REACTION_SIGNS_IGNORED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-chemistry-chemistry_atoms-12","subject_code":"CHEMISTRY","target_skill":"CHEMISTRY_ATOMS","domain":"ATOMOS","topic":"massa","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"MASSA","difficulty":"HARD","statement":"Em uma reacao fechada, a massa total permanece constante porque:","options":["Os atomos se reorganizam sem desaparecer.","A materia sai do recipiente.","Os atomos deixam de existir.","A massa depende apenas da cor."],"correct_answer":"Os atomos se reorganizam sem desaparecer.","explanation":"A conservacao da massa decorre da reorganizacao das particulas.","secondary_links":[],"misconceptions":[{"option_value":"A materia sai do recipiente.","tag_code":"MASS_CONSERVATION_DENIED","confidence_weight":0.8,"skill_code":"CHEMISTRY_ATOMS"}]},{"question_id":"v3-history-history_interpretation-1","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"fonte primaria","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"FONTE_PRIMARIA","difficulty":"EASY","statement":"Uma carta escrita por uma trabalhadora durante uma greve e uma fonte primaria porque:","options":["Foi produzida no contexto vivido pela autora.","Foi escrita muitos seculos depois.","Resume todos os livros sobre a greve.","Nao possui perspectiva."],"correct_answer":"Foi produzida no contexto vivido pela autora.","explanation":"A fonte registra o periodo, ainda que seja parcial.","secondary_links":[],"misconceptions":[{"option_value":"Foi escrita muitos seculos depois.","tag_code":"PRIMARY_SOURCE_CONFUSED_WITH_NEUTRAL","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-2","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"contexto","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"CONTEXTO","difficulty":"EASY","statement":"Para interpretar um discurso politico de 1930, e importante considerar:","options":["As disputas e valores daquele periodo.","Somente o significado atual das palavras.","A biografia de qualquer pessoa.","A data de impressao do livro escolar."],"correct_answer":"As disputas e valores daquele periodo.","explanation":"Contexto evita aplicar categorias atuais de modo anacronico.","secondary_links":[],"misconceptions":[{"option_value":"Somente o significado atual das palavras.","tag_code":"ANACHRONISM_IGNORED","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-3","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"cronologia","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"CRONOLOGIA","difficulty":"EASY","statement":"Se a abolicao ocorreu em 1888 e a Republica em 1889, qual ocorreu primeiro?","options":["A abolicao.","A Republica.","Ocorreram no mesmo ano.","Nao e possivel ordenar."],"correct_answer":"A abolicao.","explanation":"1888 antecede 1889.","secondary_links":[],"misconceptions":[{"option_value":"A Republica.","tag_code":"CHRONOLOGY_REVERSED","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-4","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"causa","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"CAUSA","difficulty":"MEDIUM","statement":"Uma crise economica aumenta o desemprego e favorece protestos. Nessa frase, o desemprego e:","options":["Uma consequencia da crise.","A causa unica da crise.","Um evento sem relacao.","Uma fonte primaria."],"correct_answer":"Uma consequencia da crise.","explanation":"A relacao apresentada coloca a crise antes do desemprego.","secondary_links":[],"misconceptions":[{"option_value":"A causa unica da crise.","tag_code":"CAUSE_EFFECT_REVERSED","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-5","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"multiperspectiva","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"MULTIPERSPECTIVA","difficulty":"MEDIUM","statement":"Um relato de colonizador e outro de comunidade indigena descrevem um encontro. O historiador deve:","options":["Comparar perspectivas, linguagem e contexto.","Eliminar o relato indigena.","Escolher o texto mais longo.","Somar as narrativas como se fossem iguais."],"correct_answer":"Comparar perspectivas, linguagem e contexto.","explanation":"Fontes revelam interesses e experiencias distintas.","secondary_links":[],"misconceptions":[{"option_value":"Eliminar o relato indigena.","tag_code":"SINGLE_NARRATIVE_ASSUMED","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-6","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"periodizacao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"PERIODIZACAO","difficulty":"MEDIUM","statement":"Dividir a historia em periodos ajuda a:","options":["Organizar processos sem supor mudancas instantaneas.","Provar que toda sociedade muda na mesma data.","Apagar continuidades.","Substituir a analise de fontes."],"correct_answer":"Organizar processos sem supor mudancas instantaneas.","explanation":"Periodizacao e uma ferramenta de analise.","secondary_links":[],"misconceptions":[{"option_value":"Provar que toda sociedade muda na mesma data.","tag_code":"PERIODIZATION_TREATED_AS_ABSOLUTE","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-7","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"memoria","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"MEMORIA","difficulty":"MEDIUM","statement":"Uma festa comemorativa preserva a memoria de um grupo, enquanto a pesquisa historica:","options":["Analisa memorias junto de outras evidencias.","Repete a comemoracao sem critica.","Ignora qualquer testemunho.","Transforma memoria em prova unica."],"correct_answer":"Analisa memorias junto de outras evidencias.","explanation":"Memoria e evidencia importante, mas precisa de contexto.","secondary_links":[],"misconceptions":[{"option_value":"Repete a comemoracao sem critica.","tag_code":"MEMORY_EQUALS_COMPLETE_HISTORY","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-8","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"mapa historico","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"MAPA_HISTORICO","difficulty":"MEDIUM","statement":"Um mapa de ferrovias de 1910 pode ajudar a investigar:","options":["Circulacao e integracao economica daquele periodo.","A temperatura atual das cidades.","A opiniao dos trabalhadores sem outras fontes.","A idade do papel."],"correct_answer":"Circulacao e integracao economica daquele periodo.","explanation":"A rede permite perguntas sobre fluxos historicos.","secondary_links":[],"misconceptions":[{"option_value":"A temperatura atual das cidades.","tag_code":"MAP_DATA_IGNORED","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-9","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"fotografia","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"FOTOGRAFIA","difficulty":"MEDIUM","statement":"Uma fotografia mostra uma rua movimentada, mas nao informa sozinha o motivo. O pesquisador deve:","options":["Cruzar a imagem com outras fontes.","Inventar o motivo mais provavel.","Considerar a foto falsa.","Concluir que toda cidade era igual."],"correct_answer":"Cruzar a imagem com outras fontes.","explanation":"A imagem documenta uma cena, mas o significado exige contexto.","secondary_links":[],"misconceptions":[{"option_value":"Inventar o motivo mais provavel.","tag_code":"IMAGE_OVERINTERPRETED","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-10","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"mudanca","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"MUDANCA","difficulty":"MEDIUM","statement":"Uma lei pode mudar direitos formais enquanto praticas sociais continuam desiguais. Isso mostra:","options":["Mudanca e permanencia podem coexistir.","Leis nunca alteram sociedades.","Praticas sociais mudam no mesmo dia.","Direitos formais nao tem historia."],"correct_answer":"Mudanca e permanencia podem coexistir.","explanation":"Processos historicos tem ritmos diferentes.","secondary_links":[],"misconceptions":[{"option_value":"Leis nunca alteram sociedades.","tag_code":"CHANGE_ERASES_CONTINUITY","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-11","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"interpretacao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"INTERPRETACAO","difficulty":"HARD","statement":"Dois historiadores usam as mesmas fontes e defendem interpretacoes diferentes. Isso pode ocorrer porque:","options":["Selecionam perguntas e argumentos diferentes.","A fonte fornece sempre uma unica leitura.","Um deles nao pode usar conceitos.","Interpretacao nao depende de evidencias."],"correct_answer":"Selecionam perguntas e argumentos diferentes.","explanation":"Evidencias limitam, mas perguntas orientam a interpretacao.","secondary_links":[],"misconceptions":[{"option_value":"A fonte fornece sempre uma unica leitura.","tag_code":"INTERPRETATION_IS_GUESS","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-history-history_interpretation-12","subject_code":"HISTORY","target_skill":"HISTORY_INTERPRETATION","domain":"INTERPRETACAO","topic":"patrimonio","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"PATRIMONIO","difficulty":"HARD","statement":"Preservar um edificio historico contribui para:","options":["Manter vestigios e debates sobre experiencias passadas.","Congelar a cidade sem uso.","Provar que o passado foi perfeito.","Apagar transformacoes posteriores."],"correct_answer":"Manter vestigios e debates sobre experiencias passadas.","explanation":"Patrimonio conecta materialidade, memoria e interpretacao.","secondary_links":[],"misconceptions":[{"option_value":"Congelar a cidade sem uso.","tag_code":"HERITAGE_ROMANTICIZED","confidence_weight":0.8,"skill_code":"HISTORY_INTERPRETATION"}]},{"question_id":"v3-geography-geography_territory-1","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"territorio","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"TERRITORIO","difficulty":"EASY","statement":"Uma comunidade controla o uso de uma area e define regras de acesso. Esse espaco e analisado como:","options":["Territorio.","Clima.","Relevo apenas.","Fuso horario."],"correct_answer":"Territorio.","explanation":"Territorio envolve poder, controle e apropriacao do espaco.","secondary_links":[],"misconceptions":[{"option_value":"Clima.","tag_code":"TERRITORY_CONFUSED_WITH_LOCATION","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-2","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"paisagem","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"PAISAGEM","difficulty":"EASY","statement":"Uma paisagem com predios, avenida e rio registra:","options":["Elementos naturais e transformacoes humanas.","Somente clima.","Apenas fronteiras politicas.","Somente atividades rurais."],"correct_answer":"Elementos naturais e transformacoes humanas.","explanation":"Paisagem reune elementos percebidos e suas marcas historicas.","secondary_links":[],"misconceptions":[{"option_value":"Somente clima.","tag_code":"LANDSCAPE_NATURAL_ONLY","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-3","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"escala","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"ESCALA","difficulty":"EASY","statement":"Em um mapa de escala grande, uma quadra aparece com mais detalhes porque:","options":["A area representada e menor e o detalhamento e maior.","Todo mapa grande mostra o planeta.","A escala nao muda o detalhe.","A legenda deixa de ser necessaria."],"correct_answer":"A area representada e menor e o detalhamento e maior.","explanation":"Escala grande permite observar area menor com mais detalhe.","secondary_links":[],"misconceptions":[{"option_value":"Todo mapa grande mostra o planeta.","tag_code":"MAP_SCALE_REVERSED","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-4","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"rede urbana","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"REDE_URBANA","difficulty":"MEDIUM","statement":"Uma cidade ligada a outras por transporte, comercio e servicos participa de:","options":["Uma rede urbana.","Um ecossistema fechado.","Uma bacia hidrografica.","Uma fronteira natural."],"correct_answer":"Uma rede urbana.","explanation":"Fluxos entre cidades formam redes de relacoes.","secondary_links":[],"misconceptions":[{"option_value":"Um ecossistema fechado.","tag_code":"URBAN_NETWORK_DENIED","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-5","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"legenda","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"LEGENDA","difficulty":"MEDIUM","statement":"A legenda de um mapa serve para:","options":["Explicar simbolos e cores usados na representacao.","Indicar apenas a orientacao do norte.","Substituir a escala.","Mostrar dados que nao foram mapeados."],"correct_answer":"Explicar simbolos e cores usados na representacao.","explanation":"A legenda permite interpretar sinais cartograficos.","secondary_links":[],"misconceptions":[{"option_value":"Indicar apenas a orientacao do norte.","tag_code":"LEGEND_CONFUSED_WITH_SCALE","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-6","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"fronteira","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"FRONTEIRA","difficulty":"MEDIUM","statement":"Uma fronteira politica pode mudar por acordos ou conflitos. Isso mostra que:","options":["Fronteiras sao construcoes historicas e politicas.","Fronteiras naturais nunca mudam.","Todo limite e apenas fisico.","Mapas nao expressam poder."],"correct_answer":"Fronteiras sao construcoes historicas e politicas.","explanation":"Limites territoriais resultam de processos sociais e politicos.","secondary_links":[],"misconceptions":[{"option_value":"Fronteiras naturais nunca mudam.","tag_code":"BORDER_TREATED_AS_NATURAL","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-7","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"uso do solo","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"USO_DO_SOLO","difficulty":"MEDIUM","statement":"A substituicao de area verde por estacionamento altera principalmente:","options":["O uso do solo e a drenagem local.","A rotacao da Terra.","A distancia ao Sol.","A composicao do nucleo terrestre."],"correct_answer":"O uso do solo e a drenagem local.","explanation":"Cobertura e uso do solo influenciam escoamento e ocupacao.","secondary_links":[],"misconceptions":[{"option_value":"A rotacao da Terra.","tag_code":"LAND_USE_EFFECT_IGNORED","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-8","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"populacao","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"POPULACAO","difficulty":"MEDIUM","statement":"Um mapa mostra concentracao de moradores perto de corredores de onibus. Uma hipotese adequada e:","options":["Transporte influencia acessibilidade e ocupacao.","Onibus determinam toda renda.","Nao existe relacao espacial possivel.","A populacao se distribui ao acaso."],"correct_answer":"Transporte influencia acessibilidade e ocupacao.","explanation":"A concentracao sugere uma relacao a investigar.","secondary_links":[],"misconceptions":[{"option_value":"Onibus determinam toda renda.","tag_code":"SPATIAL_PATTERN_OVERSTATED","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-9","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"clima e tempo","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"CLIMA_E_TEMPO","difficulty":"MEDIUM","statement":"A previsao indica chuva amanha; a media de chuvas de uma regiao em trinta anos descreve:","options":["Clima.","Tempo atmosferico de amanha.","Latitude apenas.","Relevo de uma rua."],"correct_answer":"Clima.","explanation":"Clima e o comportamento medio em periodo longo.","secondary_links":[],"misconceptions":[{"option_value":"Tempo atmosferico de amanha.","tag_code":"CLIMATE_TIME_CONFUSED","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-10","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"migracao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"MIGRACAO","difficulty":"MEDIUM","statement":"Pessoas deixam uma regiao por falta de trabalho e procuram emprego em outra. Esse movimento e:","options":["Migracao motivada por fator economico.","Rotacao terrestre.","Erosao.","Urbanizacao sem deslocamento."],"correct_answer":"Migracao motivada por fator economico.","explanation":"A mudanca de lugar tem relacao com oportunidade de trabalho.","secondary_links":[],"misconceptions":[{"option_value":"Rotacao terrestre.","tag_code":"MIGRATION_CAUSE_MISREAD","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-11","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"alagamento","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"ALAGAMENTO","difficulty":"HARD","statement":"A impermeabilizacao de muitas ruas pode aumentar alagamentos porque:","options":["A agua infiltra menos e escoa mais rapidamente.","O solo passa a absorver mais agua.","A chuva deixa de existir.","O relevo desaparece."],"correct_answer":"A agua infiltra menos e escoa mais rapidamente.","explanation":"Superficies impermeaveis reduzem infiltracao.","secondary_links":[],"misconceptions":[{"option_value":"O solo passa a absorver mais agua.","tag_code":"IMPERMEABILITY_EFFECT_REVERSED","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-geography-geography_territory-12","subject_code":"GEOGRAPHY","target_skill":"GEOGRAPHY_TERRITORY","domain":"TERRITORIO","topic":"desigualdade territorial","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"DESIGUALDADE_TERRITORIAL","difficulty":"HARD","statement":"Dois bairros tem a mesma distancia do centro, mas servicos diferentes. O que a analise deve considerar?","options":["Infraestrutura, renda, mobilidade e politicas territoriais.","Somente a distancia em linha reta.","Apenas o nome dos bairros.","A altitude como unica causa."],"correct_answer":"Infraestrutura, renda, mobilidade e politicas territoriais.","explanation":"Desigualdade territorial resulta de varios fatores articulados.","secondary_links":[],"misconceptions":[{"option_value":"Somente a distancia em linha reta.","tag_code":"DISTANCE_EXPLAINS_ALL","confidence_weight":0.8,"skill_code":"GEOGRAPHY_TERRITORY"}]},{"question_id":"v3-philosophy-philosophy_argument-1","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"justica","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"JUSTICA","difficulty":"EASY","statement":"Uma escola debate se e justo distribuir recursos igualmente ou conforme a necessidade. Qual procedimento e adequado?","options":["Definir criterios e examinar suas consequencias.","Escolher a opiniao mais popular.","Encerrar o debate com um exemplo.","Tratar justica como palavra sem sentido."],"correct_answer":"Definir criterios e examinar suas consequencias.","explanation":"A analise conceitual explicita criterios antes de julgar.","secondary_links":[],"misconceptions":[{"option_value":"Escolher a opiniao mais popular.","tag_code":"POPULARITY_REPLACES_ARGUMENT","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-2","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"premissa e conclusao","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"PREMISSA_E_CONCLUSAO","difficulty":"EASY","statement":"Em Se chove, o patio molha; chove; logo, o patio molha, qual e a conclusao?","options":["O patio molha.","Se chove.","Chove.","O patio e coberto."],"correct_answer":"O patio molha.","explanation":"A conclusao e o enunciado sustentado pelas premissas.","secondary_links":[],"misconceptions":[{"option_value":"Se chove.","tag_code":"CONCLUSION_PREMISE_SWAPPED","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-3","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"validade","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"VALIDADE","difficulty":"EASY","statement":"Um argumento pode ter forma valida e premissa falsa. O que isso significa?","options":["A conclusao segue a forma, mas o conteudo inicial precisa ser examinado.","Toda conclusao valida e verdadeira.","Premissas nunca importam.","Forma e conteudo sao a mesma coisa."],"correct_answer":"A conclusao segue a forma, mas o conteudo inicial precisa ser examinado.","explanation":"Validade trata da estrutura; verdade exige avaliar premissas.","secondary_links":[],"misconceptions":[{"option_value":"Toda conclusao valida e verdadeira.","tag_code":"VALIDITY_EQUALS_TRUTH","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-4","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"dialogo","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"DIALOGO","difficulty":"MEDIUM","statement":"Em um dialogo filosofico, responder a uma objecao relevante serve para:","options":["Testar e aperfeicoar o argumento.","Evitar qualquer criterio.","Trocar razoes por autoridade.","Provar que discordancia e erro."],"correct_answer":"Testar e aperfeicoar o argumento.","explanation":"Objecoes ajudam a identificar limites e fortalecer uma tese.","secondary_links":[],"misconceptions":[{"option_value":"Evitar qualquer criterio.","tag_code":"OBJECTION_AS_ATTACK","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-5","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"etica","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"ETICA","difficulty":"MEDIUM","statement":"Uma decisao pode beneficiar muitos, mas prejudicar um grupo vulneravel. Qual pergunta e pertinente?","options":["Como distribuir beneficios e danos de modo justificavel?","Quantas pessoas concordam nas redes?","Quem falou primeiro?","Qual escolha e mais rapida?"],"correct_answer":"Como distribuir beneficios e danos de modo justificavel?","explanation":"A avaliacao etica considera impactos e justificacao.","secondary_links":[],"misconceptions":[{"option_value":"Quantas pessoas concordam nas redes?","tag_code":"MAJORITY_REPLACES_ETHICS","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-6","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"analogia","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"ANALOGIA","difficulty":"MEDIUM","statement":"Comparar uma regra escolar com uma regra de um jogo pode ajudar quando:","options":["As semelhancas relevantes e os limites da comparacao sao explicitados.","Toda comparacao prova a conclusao.","As diferencas sao ignoradas.","Analogia dispensa razoes."],"correct_answer":"As semelhancas relevantes e os limites da comparacao sao explicitados.","explanation":"Analogia orienta, mas precisa mostrar por que a relacao e pertinente.","secondary_links":[],"misconceptions":[{"option_value":"Toda comparacao prova a conclusao.","tag_code":"ANALOGY_AS_PROOF","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-7","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"ceticismo","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"CETICISMO","difficulty":"MEDIUM","statement":"Duvidar de uma afirmacao para pedir evidencia e diferente de negar tudo porque:","options":["A duvida metodica busca criterios para avaliar.","Ceticismo impede qualquer investigacao.","Toda evidencia e opiniao.","Negacao sem razao e mais rigorosa."],"correct_answer":"A duvida metodica busca criterios para avaliar.","explanation":"Questionar com metodo nao equivale a rejeitar todo conhecimento.","secondary_links":[],"misconceptions":[{"option_value":"Ceticismo impede qualquer investigacao.","tag_code":"SKEPTICISM_AS_DENIAL","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-8","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"liberdade","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"LIBERDADE","difficulty":"MEDIUM","statement":"Se escolhas sao influenciadas por contexto social, ainda e relevante perguntar:","options":["Quais condicoes ampliam ou limitam a autonomia?","Se contexto torna toda escolha falsa.","Se liberdade so existe sem sociedade.","Se responsabilidade desaparece sempre."],"correct_answer":"Quais condicoes ampliam ou limitam a autonomia?","explanation":"A filosofia pode analisar graus e condicoes de autonomia.","secondary_links":[],"misconceptions":[{"option_value":"Se contexto torna toda escolha falsa.","tag_code":"CONTEXT_ERASES_AGENCY","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-9","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"conhecimento","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"CONHECIMENTO","difficulty":"MEDIUM","statement":"O que diferencia conhecimento de palpite em uma previsao de chuva?","options":["A justificacao e a possibilidade de exame da evidencia.","A certeza absoluta em qualquer caso.","A quantidade de pessoas que repetem a frase.","A velocidade da resposta."],"correct_answer":"A justificacao e a possibilidade de exame da evidencia.","explanation":"Conhecimento exige mais que opiniao: requer justificacao examinavel.","secondary_links":[],"misconceptions":[{"option_value":"A certeza absoluta em qualquer caso.","tag_code":"BELIEF_EQUALS_KNOWLEDGE","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-10","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"falacia","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"FALACIA","difficulty":"MEDIUM","statement":"Dizer que uma proposta e falsa apenas porque seu autor errou em outro assunto e:","options":["Ataque a pessoa em vez do argumento.","Evidencia experimental.","Definicao conceitual.","Silogismo valido."],"correct_answer":"Ataque a pessoa em vez do argumento.","explanation":"A origem pessoal nao refuta o conteudo da proposta.","secondary_links":[],"misconceptions":[{"option_value":"Evidencia experimental.","tag_code":"PERSON_ATTACK_AS_REFUTATION","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-11","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"pensamento critico","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PENSAMENTO_CRITICO","difficulty":"HARD","statement":"Ao ouvir uma afirmacao viral, uma atitude filosofica e:","options":["Perguntar conceitos, razoes, evidencias e contraexemplos.","Compartilhar antes de ler.","Aceitar se for emocional.","Rejeitar toda afirmacao."],"correct_answer":"Perguntar conceitos, razoes, evidencias e contraexemplos.","explanation":"Pensamento critico organiza perguntas antes do julgamento.","secondary_links":[],"misconceptions":[{"option_value":"Compartilhar antes de ler.","tag_code":"CRITICAL_THINKING_AS_CYNICISM","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-philosophy-philosophy_argument-12","subject_code":"PHILOSOPHY","target_skill":"PHILOSOPHY_ARGUMENT","domain":"ARGUMENTO","topic":"anecdota","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"ANECDOTA","difficulty":"HARD","statement":"Uma tese sobre transporte cita apenas um caso individual. Qual limite deve ser reconhecido?","options":["O caso ilustra, mas pode nao representar toda a cidade.","Um caso prova qualquer generalizacao.","Exemplos nunca tem valor.","A tese se torna necessariamente falsa."],"correct_answer":"O caso ilustra, mas pode nao representar toda a cidade.","explanation":"O argumento precisa ajustar a conclusao ao alcance da evidencia.","secondary_links":[],"misconceptions":[{"option_value":"Um caso prova qualquer generalizacao.","tag_code":"ANECDOTE_GENERALIZED","confidence_weight":0.8,"skill_code":"PHILOSOPHY_ARGUMENT"}]},{"question_id":"v3-sociology-sociology_institutions-1","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"instituicoes","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"INSTITUICOES","difficulty":"EASY","statement":"Familia, escola e Estado possuem regras e papeis que organizam a vida coletiva. Elas sao:","options":["Instituicoes sociais.","Apenas grupos de amigos.","Fenomenos naturais.","Objetos sem normas."],"correct_answer":"Instituicoes sociais.","explanation":"Instituicoes estruturam expectativas, papeis e praticas.","secondary_links":[],"misconceptions":[{"option_value":"Apenas grupos de amigos.","tag_code":"INSTITUTION_CONFUSED_WITH_GROUP","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-2","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"socializacao","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"SOCIALIZACAO","difficulty":"EASY","statement":"Aprender regras de convivencia desde a infancia e parte do processo de:","options":["Socializacao.","Industrializacao.","Urbanizacao.","Erosao."],"correct_answer":"Socializacao.","explanation":"Socializacao transmite normas e formas de participar da sociedade.","secondary_links":[],"misconceptions":[{"option_value":"Industrializacao.","tag_code":"SOCIALIZATION_MISNAMED","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-3","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"norma e lei","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"NORMA_E_LEI","difficulty":"EASY","statement":"Uma norma social pode existir mesmo sem estar escrita em um codigo porque:","options":["Expectativas coletivas orientam comportamentos.","Toda norma e natural.","Leis nao influenciam costumes.","Comportamentos nunca tem sancao social."],"correct_answer":"Expectativas coletivas orientam comportamentos.","explanation":"Normas podem ser informais e produzir aprovacao ou reprovacao.","secondary_links":[],"misconceptions":[{"option_value":"Toda norma e natural.","tag_code":"NORMS_ONLY_LAW","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-4","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"desigualdade","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"DESIGUALDADE","difficulty":"MEDIUM","statement":"Duas pessoas com o mesmo talento recebem oportunidades escolares diferentes por renda. Isso indica:","options":["Desigualdade de oportunidades.","Igualdade plena.","Apenas diferenca biologica.","Ausencia de estrutura social."],"correct_answer":"Desigualdade de oportunidades.","explanation":"Recursos economicos influenciam acesso e trajetorias.","secondary_links":[],"misconceptions":[{"option_value":"Igualdade plena.","tag_code":"INEQUALITY_AS_EFFORT_ONLY","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-5","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"cultura","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"CULTURA","difficulty":"MEDIUM","statement":"Uma pratica cultural muda ao entrar em contato com outras comunidades. Isso mostra que cultura:","options":["E aprendida, compartilhada e dinamica.","E fixa biologicamente.","E identica em todo lugar.","Nao possui significados."],"correct_answer":"E aprendida, compartilhada e dinamica.","explanation":"Cultura se transforma por interacao e disputas de significado.","secondary_links":[],"misconceptions":[{"option_value":"E fixa biologicamente.","tag_code":"CULTURE_AS_FIXED","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-6","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"trabalho","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"TRABALHO","difficulty":"MEDIUM","statement":"A automacao pode substituir tarefas e criar novas qualificacoes. Qual analise e mais adequada?","options":["Considerar efeitos sobre ocupacoes, qualificacao e desigualdade.","Concluir que todo trabalho desaparece.","Ignorar tecnologia.","Reduzir tudo a escolha individual."],"correct_answer":"Considerar efeitos sobre ocupacoes, qualificacao e desigualdade.","explanation":"Mudancas do trabalho tem efeitos distribuidos de forma desigual.","secondary_links":[],"misconceptions":[{"option_value":"Concluir que todo trabalho desaparece.","tag_code":"AUTOMATION_TOTALIZED","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-7","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"movimentos","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"MOVIMENTOS","difficulty":"MEDIUM","statement":"Um movimento organiza pessoas para reivindicar transporte acessivel. Ele atua principalmente:","options":["Na disputa por direitos e politicas publicas.","Apenas no consumo privado.","Sem relacao com poder.","Como fenomeno natural."],"correct_answer":"Na disputa por direitos e politicas publicas.","explanation":"Movimentos sociais articulam demandas coletivas.","secondary_links":[],"misconceptions":[{"option_value":"Apenas no consumo privado.","tag_code":"MOVEMENT_AS_PRIVATE_CHOICE","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-8","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"identidade","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"IDENTIDADE","difficulty":"MEDIUM","statement":"Uma pessoa participa de varios grupos e combina referencias diferentes. Isso indica que identidade:","options":["E plural e construida em relacoes sociais.","E determinada por um unico grupo.","Nao muda com experiencias.","Nao tem dimensao coletiva."],"correct_answer":"E plural e construida em relacoes sociais.","explanation":"Identidades sao formadas por pertencimentos e trajetorias.","secondary_links":[],"misconceptions":[{"option_value":"E determinada por um unico grupo.","tag_code":"IDENTITY_AS_SINGLE_LABEL","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-9","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"poder","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"PODER","difficulty":"MEDIUM","statement":"Uma regra define quem pode falar em uma reuniao e quais temas entram na pauta. Isso revela poder sobre:","options":["Participacao e agenda.","Clima e relevo.","Genes e celulas.","Apenas linguagem privada."],"correct_answer":"Participacao e agenda.","explanation":"Poder tambem opera definindo acesso e temas legitimados.","secondary_links":[],"misconceptions":[{"option_value":"Clima e relevo.","tag_code":"POWER_AS_FORCE_ONLY","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-10","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"pesquisa","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PESQUISA","difficulty":"MEDIUM","statement":"Uma pesquisa entrevista apenas pessoas de uma rede social. Qual cuidado e necessario?","options":["Reconhecer que a amostra pode nao representar toda a populacao.","Tratar respostas como universais.","Eliminar perguntas abertas.","Concluir causalidade automaticamente."],"correct_answer":"Reconhecer que a amostra pode nao representar toda a populacao.","explanation":"A selecao de participantes limita a generalizacao.","secondary_links":[],"misconceptions":[{"option_value":"Tratar respostas como universais.","tag_code":"SAMPLE_REPRESENTATION_IGNORED","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-11","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"instituicao e mudanca","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"INSTITUICAO_E_MUDANCA","difficulty":"HARD","statement":"Uma escola altera suas regras apos reivindicacoes de estudantes. Isso mostra que instituicoes:","options":["Podem reproduzir e tambem transformar normas.","Sao imunes a conflitos.","Existem sem participantes.","Mudam apenas por causas naturais."],"correct_answer":"Podem reproduzir e tambem transformar normas.","explanation":"Instituicoes sao historicas e disputadas.","secondary_links":[],"misconceptions":[{"option_value":"Sao imunes a conflitos.","tag_code":"INSTITUTIONS_AS_IMMUTABLE","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-sociology-sociology_institutions-12","subject_code":"SOCIOLOGY","target_skill":"SOCIOLOGY_INSTITUTIONS","domain":"INSTITUICOES","topic":"midia","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"MIDIA","difficulty":"HARD","statement":"Uma campanha viraliza e muda a pauta de uma reuniao municipal. A analise deve observar:","options":["Como comunicacao, poder e participacao se articulam.","Somente o numero de curtidas.","A tecnologia como causa unica.","A ausencia de atores sociais."],"correct_answer":"Como comunicacao, poder e participacao se articulam.","explanation":"Mediacoes digitais alteram circulacao de demandas sem explicar tudo sozinhas.","secondary_links":[],"misconceptions":[{"option_value":"Somente o numero de curtidas.","tag_code":"MEDIA_TECHNOLOGY_DETERMINISM","confidence_weight":0.8,"skill_code":"SOCIOLOGY_INSTITUTIONS"}]},{"question_id":"v3-art-art_interpretation-1","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"composicao","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"COMPOSICAO","difficulty":"EASY","statement":"Uma fotografia usa linhas diagonais para conduzir o olhar ate uma janela iluminada. Qual elemento esta em destaque?","options":["Direcao e composicao.","Apenas o suporte fisico.","O preco da fotografia.","A biografia do observador."],"correct_answer":"Direcao e composicao.","explanation":"Linhas podem organizar o percurso visual na imagem.","secondary_links":[],"misconceptions":[{"option_value":"Apenas o suporte fisico.","tag_code":"FORM_IGNORED_FOR_CONTENT","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-2","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"contraste","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"CONTRASTE","difficulty":"EASY","statement":"Em uma pintura, azul escuro ao lado de amarelo intenso cria forte:","options":["Contraste de cor.","Perspectiva linear.","Textura sonora.","Escala temporal."],"correct_answer":"Contraste de cor.","explanation":"A oposicao de matizes aumenta a diferenca visual percebida.","secondary_links":[],"misconceptions":[{"option_value":"Perspectiva linear.","tag_code":"CONTRAST_CONFUSED_WITH_TEXTURE","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-3","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"contexto da obra","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"CONTEXTO_DA_OBRA","difficulty":"EASY","statement":"Para interpretar um mural sobre trabalho urbano, e importante observar:","options":["Tema, local, periodo e escolhas visuais.","Somente o tamanho do mural.","A opiniao de um unico espectador.","A tinta como prova de autoria."],"correct_answer":"Tema, local, periodo e escolhas visuais.","explanation":"Contexto amplia a leitura sem substituir a observacao.","secondary_links":[],"misconceptions":[{"option_value":"Somente o tamanho do mural.","tag_code":"ART_CONTEXT_REDUCED_TO_DATE","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-4","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"abstracao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"ABSTRACAO","difficulty":"MEDIUM","statement":"Uma obra nao representa objetos reconheciveis, mas repete formas geometricas. Uma leitura adequada e:","options":["Analisar ritmo, forma, cor e relacoes visuais.","Concluir que nao existe significado.","Procurar uma fotografia escondida.","Ignorar toda composicao."],"correct_answer":"Analisar ritmo, forma, cor e relacoes visuais.","explanation":"Abstracao organiza sentidos por elementos visuais.","secondary_links":[],"misconceptions":[{"option_value":"Concluir que nao existe significado.","tag_code":"ABSTRACTION_AS_MEANINGLESS","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-5","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"patrimonio","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"PATRIMONIO","difficulty":"MEDIUM","statement":"Uma comunidade restaura um painel antigo e registra relatos de moradores. O projeto valoriza:","options":["Memoria, materialidade e participacao.","Apenas o valor comercial.","A obra sem contexto.","A substituicao do painel por publicidade."],"correct_answer":"Memoria, materialidade e participacao.","explanation":"Patrimonio envolve objeto e significados da comunidade.","secondary_links":[],"misconceptions":[{"option_value":"Apenas o valor comercial.","tag_code":"HERITAGE_AS_COMMODITY_ONLY","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-6","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"hierarquia visual","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"HIERARQUIA_VISUAL","difficulty":"MEDIUM","statement":"Uma imagem mostra uma figura central maior que as demais. O tamanho pode sugerir:","options":["Hierarquia ou destaque.","Somente distancia real.","Ausencia de composicao.","Um movimento sonoro."],"correct_answer":"Hierarquia ou destaque.","explanation":"Escala visual orienta a atencao no conjunto.","secondary_links":[],"misconceptions":[{"option_value":"Somente distancia real.","tag_code":"SCALE_AS_REAL_SIZE_ONLY","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-7","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"arte e sociedade","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"ARTE_E_SOCIEDADE","difficulty":"MEDIUM","statement":"Um cartaz de campanha apresenta cores nacionais e pessoas diversas. Para interpreta-lo, vale perguntar:","options":["Que valores e identidades a imagem procura mobilizar.","Apenas quem fabricou o papel.","Se a cor e bonita sem contexto.","Se toda campanha e neutra."],"correct_answer":"Que valores e identidades a imagem procura mobilizar.","explanation":"Imagens publicas comunicam valores e pertencimentos.","secondary_links":[],"misconceptions":[{"option_value":"Apenas quem fabricou o papel.","tag_code":"IMAGE_AS_NEUTRAL","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-8","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"tecnica","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"TECNICA","difficulty":"MEDIUM","statement":"Uma gravura apresenta marcas repetidas e areas de tinta mais espessas. A observacao pode investigar:","options":["Como a tecnica produz textura e contraste.","Somente a idade do artista.","O som emitido pela tinta.","A ausencia de materialidade."],"correct_answer":"Como a tecnica produz textura e contraste.","explanation":"Procedimentos materiais tambem participam do sentido visual.","secondary_links":[],"misconceptions":[{"option_value":"Somente a idade do artista.","tag_code":"TECHNIQUE_IGNORED","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-9","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"perspectiva","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"PERSPECTIVA","difficulty":"MEDIUM","statement":"Linhas que parecem convergir ao longe criam efeito de:","options":["Perspectiva.","Colagem sonora.","Contraste termico.","Textura tatil real."],"correct_answer":"Perspectiva.","explanation":"A convergencia organiza profundidade na imagem.","secondary_links":[],"misconceptions":[{"option_value":"Colagem sonora.","tag_code":"PERSPECTIVE_CONFUSED","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-10","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"interpretacao plural","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"INTERPRETACAO_PLURAL","difficulty":"MEDIUM","statement":"Duas pessoas interpretam uma obra de modos diferentes e apontam elementos observaveis. Isso mostra que:","options":["Leituras podem ser plurais quando justificadas pela obra.","Qualquer leitura vale sem evidencia.","A obra tem um unico significado obrigatorio.","Observacao impede interpretacao."],"correct_answer":"Leituras podem ser plurais quando justificadas pela obra.","explanation":"Interpretacao admite diversidade com argumentos visuais.","secondary_links":[],"misconceptions":[{"option_value":"Qualquer leitura vale sem evidencia.","tag_code":"PLURALITY_AS_ANYTHING_GOES","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-11","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"processo criativo","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PROCESSO_CRIATIVO","difficulty":"HARD","statement":"Um sketchbook mostra varias tentativas antes da obra final. O material evidencia:","options":["Decisoes e revisoes do processo criativo.","Que a obra final foi automatica.","Que rascunhos nao tem valor.","A impossibilidade de planejar."],"correct_answer":"Decisoes e revisoes do processo criativo.","explanation":"Rascunhos tornam visiveis escolhas e experimentacoes.","secondary_links":[],"misconceptions":[{"option_value":"Que a obra final foi automatica.","tag_code":"PROCESS_HIDDEN","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-art-art_interpretation-12","subject_code":"ART","target_skill":"ART_INTERPRETATION","domain":"INTERPRETACAO","topic":"curadoria","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"CURADORIA","difficulty":"HARD","statement":"Uma exposicao organiza obras por tema e explica os criterios em um texto. A curadoria:","options":["Cria um percurso de leitura para o publico.","Define um unico sentido imutavel.","Substitui as obras.","Serve apenas para vender ingressos."],"correct_answer":"Cria um percurso de leitura para o publico.","explanation":"Curadoria relaciona obras sem impedir leituras do visitante.","secondary_links":[],"misconceptions":[{"option_value":"Define um unico sentido imutavel.","tag_code":"CURATION_AS_AUTHORITARIAN","confidence_weight":0.8,"skill_code":"ART_INTERPRETATION"}]},{"question_id":"v3-physical_education-pe_sport_principles-1","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"ocupacao","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"OCUPACAO","difficulty":"EASY","statement":"Em um jogo coletivo, manter a equipe espalhada pode criar linhas de passe. Qual principio aparece?","options":["Ocupacao de espacos.","Imobilidade obrigatoria.","Falta tecnica.","Aquecimento passivo."],"correct_answer":"Ocupacao de espacos.","explanation":"A distribuicao espacial amplia opcoes de passe e ataque.","secondary_links":[],"misconceptions":[{"option_value":"Imobilidade obrigatoria.","tag_code":"SPACE_OCCUPATION_IGNORED","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-2","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"defesa","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"DEFESA","difficulty":"EASY","statement":"Uma equipe marca a linha de passe e protege a area central. Essa acao busca:","options":["Reduzir opcoes do adversario.","Aumentar o espaco adversario.","Evitar qualquer comunicacao.","Substituir o aquecimento."],"correct_answer":"Reduzir opcoes do adversario.","explanation":"A defesa organiza cobertura e limita caminhos.","secondary_links":[],"misconceptions":[{"option_value":"Aumentar o espaco adversario.","tag_code":"DEFENSE_AS_CHASING_ONLY","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-3","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"fair play","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"FAIR_PLAY","difficulty":"EASY","statement":"Dois jogadores discordam de uma falta e consultam a regra antes de retomar. A atitude expressa:","options":["Respeito as regras e ao dialogo.","Vantagem a qualquer custo.","Recusa da arbitragem.","Ausencia de cooperacao."],"correct_answer":"Respeito as regras e ao dialogo.","explanation":"Fair play inclui respeito mesmo em conflito.","secondary_links":[],"misconceptions":[{"option_value":"Vantagem a qualquer custo.","tag_code":"FAIR_PLAY_AS_WINNING","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-4","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"aquecimento","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"AQUECIMENTO","difficulty":"MEDIUM","statement":"Antes de uma atividade intensa, a turma realiza movimentos graduais. A finalidade e:","options":["Preparar o corpo para a atividade.","Garantir desempenho identico.","Substituir todas as aulas.","Evitar qualquer esforco."],"correct_answer":"Preparar o corpo para a atividade.","explanation":"Aquecimento eleva gradualmente a demanda.","secondary_links":[],"misconceptions":[{"option_value":"Garantir desempenho identico.","tag_code":"WARMUP_GUARANTEES_RESULT","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-5","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"passe e apoio","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"PASSE_E_APOIO","difficulty":"MEDIUM","statement":"No futsal, um jogador passa e se desloca para oferecer nova linha de passe. Isso e:","options":["Criar apoio ao portador da bola.","Abandonar a jogada.","Impedir circulacao.","Fazer uma falta."],"correct_answer":"Criar apoio ao portador da bola.","explanation":"O deslocamento sem bola amplia possibilidades coletivas.","secondary_links":[],"misconceptions":[{"option_value":"Abandonar a jogada.","tag_code":"OFF_BALL_MOVEMENT_IGNORED","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-6","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"ritmo","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"RITMO","difficulty":"MEDIUM","statement":"Em uma corrida de resistencia, controlar o ritmo ajuda a:","options":["Sustentar o esforco ao longo do tempo.","Aumentar a velocidade sem limite.","Evitar qualquer respiracao.","Garantir a mesma marca para todos."],"correct_answer":"Sustentar o esforco ao longo do tempo.","explanation":"Ritmo relaciona intensidade e duracao.","secondary_links":[],"misconceptions":[{"option_value":"Aumentar a velocidade sem limite.","tag_code":"ENDURANCE_AS_SPRINT","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-7","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"inclusao","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"INCLUSAO","difficulty":"MEDIUM","statement":"Adaptar o tamanho da quadra e a regra de tempo para uma turma diversa favorece:","options":["Participacao com equidade.","Exclusao de quem precisa de apoio.","Competicao sem regras.","Abolicao do objetivo da atividade."],"correct_answer":"Participacao com equidade.","explanation":"A adaptacao remove barreiras sem retirar o sentido.","secondary_links":[],"misconceptions":[{"option_value":"Exclusao de quem precisa de apoio.","tag_code":"EQUITY_CONFUSED_WITH_EQUALITY","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-8","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"tatica","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"TATICA","difficulty":"MEDIUM","statement":"Em um jogo, a equipe troca passes para deslocar a defesa antes de finalizar. A estrategia prioriza:","options":["Circulacao e criacao de espacos.","Chutes aleatorios.","Defesa individual parada.","Interrupcao do jogo."],"correct_answer":"Circulacao e criacao de espacos.","explanation":"Troca de passes pode abrir linhas.","secondary_links":[],"misconceptions":[{"option_value":"Chutes aleatorios.","tag_code":"TACTIC_AS_INDIVIDUAL_SKILL","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-9","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"regras","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"REGRAS","difficulty":"MEDIUM","statement":"No voleibol, a equipe deve respeitar o limite de toques antes de enviar a bola. A regra organiza:","options":["A continuidade e a participacao coletiva.","Somente a altura da rede.","A cor da bola.","A velocidade do saque."],"correct_answer":"A continuidade e a participacao coletiva.","explanation":"Limites de toque estruturam a dinamica.","secondary_links":[],"misconceptions":[{"option_value":"Somente a altura da rede.","tag_code":"RULE_SCOPE_MISREAD","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-10","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"saude","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"SAUDE","difficulty":"MEDIUM","statement":"Durante atividade intensa, perceber tontura e comunicar ao professor e importante porque:","options":["Permite interromper e avaliar a situacao.","Prova falta de vontade.","Garante melhor resultado.","Substitui a hidratacao."],"correct_answer":"Permite interromper e avaliar a situacao.","explanation":"Percepcao corporal e comunicacao ajudam na seguranca.","secondary_links":[],"misconceptions":[{"option_value":"Prova falta de vontade.","tag_code":"BODY_SIGNAL_IGNORED","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-11","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"cooperacao","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"COOPERACAO","difficulty":"HARD","statement":"Uma equipe reorganiza a estrategia para que todos participem de uma atividade. Isso demonstra:","options":["Cooperacao e responsabilidade coletiva.","Apenas busca por recorde.","Ausencia de objetivo.","Competicao individual."],"correct_answer":"Cooperacao e responsabilidade coletiva.","explanation":"Participacao de todos exige decisao coletiva.","secondary_links":[],"misconceptions":[{"option_value":"Apenas busca por recorde.","tag_code":"COOPERATION_AS_NO_RULES","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-physical_education-pe_sport_principles-12","subject_code":"PHYSICAL_EDUCATION","target_skill":"PE_SPORT_PRINCIPLES","domain":"ESPORTES","topic":"observacao","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"OBSERVACAO","difficulty":"HARD","statement":"Ao analisar um jogo, observar deslocamentos, passes e escolhas taticas permite:","options":["Compreender o desempenho sem reduzir a pessoa ao resultado.","Medir apenas velocidade.","Definir valor pessoal do jogador.","Ignorar contexto e regras."],"correct_answer":"Compreender o desempenho sem reduzir a pessoa ao resultado.","explanation":"Analise observacional considera comportamento e contexto.","secondary_links":[],"misconceptions":[{"option_value":"Medir apenas velocidade.","tag_code":"PERFORMANCE_AS_PERSONAL_WORTH","confidence_weight":0.8,"skill_code":"PE_SPORT_PRINCIPLES"}]},{"question_id":"v3-english-english_reading-1","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"main idea","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"MAIN_IDEA","difficulty":"EASY","statement":"Read: The school garden supplies herbs for the cafeteria and gives students a place to study insects. What is the main idea?","options":["The garden supports food and learning.","The garden is used only for sports.","Students avoid science.","The cafeteria closed."],"correct_answer":"The garden supports food and learning.","explanation":"The answer combines the two purposes in the text.","secondary_links":[],"misconceptions":[{"option_value":"The garden is used only for sports.","tag_code":"MAIN_IDEA_CONFUSED_WITH_DETAIL","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-2","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"literal detail","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"LITERAL_DETAIL","difficulty":"EASY","statement":"Read: The workshop starts at 9 a.m. on Saturday. When does it start?","options":["At 9 a.m. on Saturday.","At 8 p.m. on Friday.","At noon on Sunday.","At 10 a.m. on Monday."],"correct_answer":"At 9 a.m. on Saturday.","explanation":"The answer repeats the explicit time and day.","secondary_links":[],"misconceptions":[{"option_value":"At 8 p.m. on Friday.","tag_code":"EXPLICIT_DETAIL_IGNORED","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-3","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"vocabulary","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"VOCABULARY","difficulty":"EASY","statement":"In The path is narrow, but safe, the word narrow means:","options":["Not wide.","Very fast.","Extremely loud.","Full of water."],"correct_answer":"Not wide.","explanation":"Narrow describes limited width.","secondary_links":[],"misconceptions":[{"option_value":"Very fast.","tag_code":"VOCABULARY_LITERAL_MISREAD","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-4","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"inference","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"INFERENCE","difficulty":"MEDIUM","statement":"Read: Maya took an umbrella after checking the dark clouds. What can we infer?","options":["She expected rain.","She had lost her bicycle.","She was going swimming.","The sun was very strong."],"correct_answer":"She expected rain.","explanation":"The action and clouds support this inference.","secondary_links":[],"misconceptions":[{"option_value":"She had lost her bicycle.","tag_code":"INFERENCE_AS_CERTAINTY","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-5","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"reference","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"REFERENCE","difficulty":"MEDIUM","statement":"In The team planted trees because they wanted more shade, they refers to:","options":["The team.","The trees.","The shade.","The street."],"correct_answer":"The team.","explanation":"The pronoun agrees with the group doing the planting.","secondary_links":[],"misconceptions":[{"option_value":"The trees.","tag_code":"PRONOUN_REFERENCE_MISREAD","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-6","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"sequence","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"SEQUENCE","difficulty":"MEDIUM","statement":"First Ana measured the soil, then she added seeds. What happened first?","options":["She measured the soil.","She added seeds.","She watered flowers.","She closed the garden."],"correct_answer":"She measured the soil.","explanation":"First marks the initial action.","secondary_links":[],"misconceptions":[{"option_value":"She added seeds.","tag_code":"SEQUENCE_REVERSED","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-7","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"purpose","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"PURPOSE","difficulty":"MEDIUM","statement":"A poster says Bring a reusable bottle to reduce waste. Its purpose is to:","options":["Encourage an action.","Report yesterday weather.","Tell a fictional story.","Define a musical note."],"correct_answer":"Encourage an action.","explanation":"The imperative invites the reader to act.","secondary_links":[],"misconceptions":[{"option_value":"Report yesterday weather.","tag_code":"GENRE_PURPOSE_MISREAD","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-8","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"contrast","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"CONTRAST","difficulty":"MEDIUM","statement":"The text says The bus is slower, but it is cheaper. What contrast is presented?","options":["Speed and cost.","Weather and food.","Age and height.","Noise and color."],"correct_answer":"Speed and cost.","explanation":"But connects two contrasting qualities.","secondary_links":[],"misconceptions":[{"option_value":"Weather and food.","tag_code":"CONTRAST_CONNECTOR_IGNORED","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-9","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"evidence","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"EVIDENCE","difficulty":"MEDIUM","statement":"Read: The river level fell after three weeks without rain. Which statement is supported?","options":["Lack of rain was associated with a lower river level.","Rain always increases pollution.","The river disappeared forever.","No one measured the river."],"correct_answer":"Lack of rain was associated with a lower river level.","explanation":"The statement stays within the evidence.","secondary_links":[],"misconceptions":[{"option_value":"Rain always increases pollution.","tag_code":"EVIDENCE_OVERGENERALIZED","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-10","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"summary","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"SUMMARY","difficulty":"MEDIUM","statement":"A paragraph describes a student reading, taking notes and comparing sources. Which summary is best?","options":["The student studies by reading and checking sources.","The student only copies a title.","The student avoids all evidence.","The student writes a fictional poem."],"correct_answer":"The student studies by reading and checking sources.","explanation":"The summary keeps the central actions.","secondary_links":[],"misconceptions":[{"option_value":"The student only copies a title.","tag_code":"SUMMARY_ADDS_DETAIL","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-11","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"prefix","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PREFIX","difficulty":"HARD","statement":"In unhappy, the prefix un- most likely means:","options":["Not.","Again.","Before.","Very."],"correct_answer":"Not.","explanation":"Un- commonly negates the adjective.","secondary_links":[],"misconceptions":[{"option_value":"Again.","tag_code":"PREFIX_MEANING_MISREAD","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-english-english_reading-12","subject_code":"ENGLISH","target_skill":"ENGLISH_READING","domain":"LEITURA","topic":"critical reading","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"CRITICAL_READING","difficulty":"HARD","statement":"A post claims one drink improves every exam result but gives no source. What is the best response?","options":["Ask for evidence before accepting the claim.","Share it because it sounds positive.","Assume every claim is false.","Ignore the wording and buy it."],"correct_answer":"Ask for evidence before accepting the claim.","explanation":"Critical reading checks the claim and its support.","secondary_links":[],"misconceptions":[{"option_value":"Share it because it sounds positive.","tag_code":"CLAIM_WITHOUT_EVIDENCE_ACCEPTED","confidence_weight":0.8,"skill_code":"ENGLISH_READING"}]},{"question_id":"v3-religious_education-religious_diversity-1","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"traditions","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"TRADITIONS","difficulty":"EASY","statement":"A class compares harvest celebrations from different communities. A respectful study should:","options":["Describe practices in their own contexts.","Rank traditions as better or worse.","Assume all practices are identical.","Replace accounts with stereotypes."],"correct_answer":"Describe practices in their own contexts.","explanation":"Contextual description avoids hierarchy and caricature.","secondary_links":[],"misconceptions":[{"option_value":"Rank traditions as better or worse.","tag_code":"TRADITION_RANKING","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-2","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"diversity","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"DIVERSITY","difficulty":"EASY","statement":"Students hear different beliefs about the origin of life. A plural dialogue asks them to:","options":["Listen, identify differences and discuss respectfully.","Force one belief on everyone.","Mock disagreement.","Erase all religious vocabulary."],"correct_answer":"Listen, identify differences and discuss respectfully.","explanation":"Plural education protects dialogue and dignity.","secondary_links":[],"misconceptions":[{"option_value":"Force one belief on everyone.","tag_code":"DIALOGUE_CONFUSED_WITH_CONVERSION","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-3","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"secular context","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"SECULAR_CONTEXT","difficulty":"EASY","statement":"A public school studies religion without requiring adherence. The educational approach is:","options":["Descriptive and non-confessional.","A worship service.","A test of personal faith.","A ranking of families."],"correct_answer":"Descriptive and non-confessional.","explanation":"The class studies phenomena without imposing belief.","secondary_links":[],"misconceptions":[{"option_value":"A worship service.","tag_code":"DESCRIPTIVE_STUDY_AS_WORSHIP","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-4","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"ritual","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"RITUAL","difficulty":"MEDIUM","statement":"A ritual may include gestures, objects and words meaningful to a community. To understand it, one should:","options":["Ask what meanings participants attribute to it.","Assume every ritual has the same meaning.","Treat objects as decoration only.","Ignore the community."],"correct_answer":"Ask what meanings participants attribute to it.","explanation":"Meaning is connected to practice and community.","secondary_links":[],"misconceptions":[{"option_value":"Assume every ritual has the same meaning.","tag_code":"RITUAL_REDUCED_TO_OBJECT","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-5","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"respect","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"RESPECT","difficulty":"MEDIUM","statement":"A student asks a colleague about a tradition. Which question is respectful?","options":["Como voce interpreta essa pratica?","Por que sua tradicao e estranha?","Voce acredita em tudo sem pensar?","Sua familia nao tem ciencia?"],"correct_answer":"Como voce interpreta essa pratica?","explanation":"The question invites explanation without judgment.","secondary_links":[],"misconceptions":[{"option_value":"Por que sua tradicao e estranha?","tag_code":"STEREOTYPE_AS_QUESTION","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-6","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"internal diversity","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"INTERNAL_DIVERSITY","difficulty":"MEDIUM","statement":"There can be different interpretations within the same tradition. This shows that traditions:","options":["Have internal diversity and historical change.","Are identical for every member.","Never change over time.","Have no social context."],"correct_answer":"Have internal diversity and historical change.","explanation":"Communities interpret and live traditions in varied ways.","secondary_links":[],"misconceptions":[{"option_value":"Are identical for every member.","tag_code":"TRADITION_AS_MONOLITH","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-7","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"worldviews","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"WORLDVIEWS","difficulty":"MEDIUM","statement":"A worldview may connect ideas about meaning, nature and community. A careful study should:","options":["Examine how these ideas relate in a specific context.","Assume every worldview rejects science.","Reduce it to one slogan.","Separate it from any lived practice."],"correct_answer":"Examine how these ideas relate in a specific context.","explanation":"Worldviews are systems of meaning, not isolated labels.","secondary_links":[],"misconceptions":[{"option_value":"Assume every worldview rejects science.","tag_code":"WORLDVIEW_REDUCED_TO_SLOGAN","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-8","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"freedom","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"FREEDOM","difficulty":"MEDIUM","statement":"Respecting freedom of belief in school means:","options":["Protecting different convictions and the right not to adhere.","Requiring one answer from everyone.","Allowing insults as debate.","Ignoring discrimination."],"correct_answer":"Protecting different convictions and the right not to adhere.","explanation":"Freedom includes belief, non-belief and protection from coercion.","secondary_links":[],"misconceptions":[{"option_value":"Requiring one answer from everyone.","tag_code":"FREEDOM_AS_MAJORITY_RULE","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-9","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"source","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"SOURCE","difficulty":"MEDIUM","statement":"An oral account of a festival should be studied with attention to:","options":["Who speaks, in what context and for what purpose.","Only the date in a calendar.","A stereotype from another group.","A single outsider opinion."],"correct_answer":"Who speaks, in what context and for what purpose.","explanation":"Source context helps interpret voice and meaning.","secondary_links":[],"misconceptions":[{"option_value":"Only the date in a calendar.","tag_code":"SOURCE_CONTEXT_IGNORED","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-10","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"symbol","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"SYMBOL","difficulty":"MEDIUM","statement":"A symbol can have different meanings in different communities. The safest interpretation is to:","options":["Use the community context before generalizing.","Assign the same meaning everywhere.","Assume symbols have no meaning.","Choose the most exotic explanation."],"correct_answer":"Use the community context before generalizing.","explanation":"Meaning is situated and should not be projected from outside.","secondary_links":[],"misconceptions":[{"option_value":"Assign the same meaning everywhere.","tag_code":"SYMBOL_MEANING_UNIVERSALIZED","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-11","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"prejudice","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PREJUDICE","difficulty":"HARD","statement":"Calling a whole community violent based on one news story is:","options":["A stereotype and an unjustified generalization.","A careful comparative method.","A neutral description.","A source criticism."],"correct_answer":"A stereotype and an unjustified generalization.","explanation":"One case cannot define a diverse community.","secondary_links":[],"misconceptions":[{"option_value":"A careful comparative method.","tag_code":"SINGLE_CASE_STEREOTYPE","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-religious_education-religious_diversity-12","subject_code":"RELIGIOUS_EDUCATION","target_skill":"RELIGIOUS_DIVERSITY","domain":"DIVERSIDADE","topic":"dialogue norms","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"DIALOGUE_NORMS","difficulty":"HARD","statement":"A productive classroom dialogue about belief should include:","options":["Turn-taking, evidence, respect and space for disagreement.","Interruption and ridicule.","A vote to silence minorities.","Personal attacks."],"correct_answer":"Turn-taking, evidence, respect and space for disagreement.","explanation":"Dialogue rules protect participation and dignity.","secondary_links":[],"misconceptions":[{"option_value":"Interruption and ridicule.","tag_code":"DIALOGUE_AS_CONFLICT","confidence_weight":0.8,"skill_code":"RELIGIOUS_DIVERSITY"}]},{"question_id":"v3-computing-computing_algorithms-1","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"decomposition","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"DECOMPOSITION","difficulty":"EASY","statement":"To plan a school app, the team lists login, schedule and messages as separate tasks. This is:","options":["Decomposition.","Encryption.","Randomization.","Compression."],"correct_answer":"Decomposition.","explanation":"Breaking a problem into smaller tasks makes it manageable.","secondary_links":[],"misconceptions":[{"option_value":"Encryption.","tag_code":"DECOMPOSITION_CONFUSED_WITH_CODING","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-2","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"sequence","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"SEQUENCE","difficulty":"EASY","statement":"An algorithm says: receive score, add points, display total. What concept is shown?","options":["Sequence of steps.","A loop without condition.","A password.","A network address."],"correct_answer":"Sequence of steps.","explanation":"The instructions run in an ordered progression.","secondary_links":[],"misconceptions":[{"option_value":"A loop without condition.","tag_code":"SEQUENCE_ORDER_IGNORED","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-3","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"condition","purpose":"PROBE","cognitive_process":"IDENTIFY","context_family":"CONDITION","difficulty":"EASY","statement":"If the temperature is below 18, show a coat reminder. The if statement represents:","options":["A condition.","A file format.","A variable name only.","A drawing tool."],"correct_answer":"A condition.","explanation":"The action depends on a true or false test.","secondary_links":[],"misconceptions":[{"option_value":"A file format.","tag_code":"CONDITION_CONFUSED_WITH_ACTION","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-4","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"loop","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"LOOP","difficulty":"MEDIUM","statement":"A program repeats reading names until the list ends. Which structure is useful?","options":["A loop.","A single constant.","A color palette.","A manual screenshot."],"correct_answer":"A loop.","explanation":"Repetition avoids writing the same step for every name.","secondary_links":[],"misconceptions":[{"option_value":"A single constant.","tag_code":"LOOP_AS_SINGLE_STEP","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-5","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"debugging","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"DEBUGGING","difficulty":"MEDIUM","statement":"The app totals 2 + 3 as 23 because values were read as text. What is debugging here?","options":["Finding and correcting the type error.","Deleting the whole app.","Changing the screen color.","Adding a random delay."],"correct_answer":"Finding and correcting the type error.","explanation":"The behavior points to a data representation problem.","secondary_links":[],"misconceptions":[{"option_value":"Deleting the whole app.","tag_code":"DEBUGGING_AS_RESTART","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-6","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"trace","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"TRACE","difficulty":"MEDIUM","statement":"A trace table records variable values after each step. Its purpose is to:","options":["Follow the algorithm state.","Hide input data.","Encrypt every variable.","Replace testing."],"correct_answer":"Follow the algorithm state.","explanation":"Tracing makes intermediate results visible for checking.","secondary_links":[],"misconceptions":[{"option_value":"Hide input data.","tag_code":"TRACE_AS_OUTPUT_ONLY","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-7","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"binary","purpose":"PRACTICE","cognitive_process":"APPLY","context_family":"BINARY","difficulty":"MEDIUM","statement":"A computer stores a black-and-white pixel using 0 and 1. This illustrates:","options":["Digital binary representation.","A natural language sentence.","A physical analog meter.","A password policy."],"correct_answer":"Digital binary representation.","explanation":"Binary symbols encode discrete states.","secondary_links":[],"misconceptions":[{"option_value":"A natural language sentence.","tag_code":"BINARY_AS_DECIMAL_ONLY","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-8","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"data privacy","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"DATA_PRIVACY","difficulty":"MEDIUM","statement":"An app asks for a student location when it only needs a class name. A better design is to:","options":["Collect only the data needed for the purpose.","Collect every possible field.","Publish the location.","Disable all access controls."],"correct_answer":"Collect only the data needed for the purpose.","explanation":"Data minimization reduces unnecessary exposure.","secondary_links":[],"misconceptions":[{"option_value":"Collect every possible field.","tag_code":"DATA_MINIMIZATION_IGNORED","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-9","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"password security","purpose":"TRANSFER","cognitive_process":"INTERPRET","context_family":"PASSWORD_SECURITY","difficulty":"MEDIUM","statement":"A service stores passwords with a one-way hash and salt. The main goal is:","options":["Reduce exposure if stored data leaks.","Make passwords public.","Recover every original password.","Avoid user authentication."],"correct_answer":"Reduce exposure if stored data leaks.","explanation":"Hashing and salting protect stored representations.","secondary_links":[],"misconceptions":[{"option_value":"Make passwords public.","tag_code":"HASH_AS_ENCRYPTION_RECOVERY","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-10","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"algorithm fairness","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"ALGORITHM_FAIRNESS","difficulty":"MEDIUM","statement":"A school recommendation model uses attendance as the only signal. A responsible review should ask:","options":["Whether the signal creates unfair effects or misses context.","Whether the model can never be wrong.","Whether students should lose access.","Whether context is irrelevant."],"correct_answer":"Whether the signal creates unfair effects or misses context.","explanation":"Responsible computing examines effects and limits.","secondary_links":[],"misconceptions":[{"option_value":"Whether the model can never be wrong.","tag_code":"SINGLE_SIGNAL_AS_NEUTRAL","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-11","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"protocol","purpose":"LOCK_IN","cognitive_process":"ANALYZE","context_family":"PROTOCOL","difficulty":"HARD","statement":"A browser requests a page and a server returns data. This exchange follows:","options":["A communication protocol.","A spreadsheet formula.","A drawing layer.","A battery charge."],"correct_answer":"A communication protocol.","explanation":"Protocols define how systems exchange messages.","secondary_links":[],"misconceptions":[{"option_value":"A spreadsheet formula.","tag_code":"PROTOCOL_CONFUSED_WITH_DEVICE","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]},{"question_id":"v3-computing-computing_algorithms-12","subject_code":"COMPUTING","target_skill":"COMPUTING_ALGORITHMS","domain":"PENSAMENTO_COMPUTACIONAL","topic":"digital citizenship","purpose":"REVIEW","cognitive_process":"EVALUATE","context_family":"DIGITAL_CITIZENSHIP","difficulty":"HARD","statement":"Before forwarding a dramatic post, a student checks source, date and evidence. This is:","options":["Responsible digital citizenship.","Data deletion.","A sorting algorithm.","A hardware repair."],"correct_answer":"Responsible digital citizenship.","explanation":"Checking context reduces harmful misinformation sharing.","secondary_links":[],"misconceptions":[{"option_value":"Data deletion.","tag_code":"SHARING_BEFORE_CHECKING","confidence_weight":0.8,"skill_code":"COMPUTING_ALGORITHMS"}]}]'::jsonb;

  -- Validate every authored target before mutating the question bank.
  for content_row in
    select * from jsonb_to_recordset(v3_question_pack) as item(
      question_id text, subject_code text, target_skill text, domain text,
      topic text, purpose text, cognitive_process text, context_family text,
      difficulty text, statement text, options jsonb, correct_answer text,
      explanation text, secondary_links jsonb, misconceptions jsonb
    )
  loop
    select subject.code as subject_code, skill.id as target_id
      into target_row
      from public.learning_canonical_subjects subject
      join public.learning_curriculum_skills skill
        on skill.canonical_subject_id = subject.id
       and skill.catalog_id = v_catalog_id
       and skill.code = content_row.target_skill
       and skill.active
     where subject.code = content_row.subject_code and subject.active;
    if not found or target_row.target_id is null then
      raise exception 'ADAPTIVE_V3_CONTENT_TARGET_MISSING: % (% / %)',
        content_row.question_id, content_row.subject_code, content_row.target_skill;
    end if;
    v_expected_content_count := v_expected_content_count + 1;
  end loop;
  if v_expected_content_count <> 180 then
    raise exception 'ADAPTIVE_V3_CONTENT_PREFLIGHT_INCOMPLETE: expected 180 questions, found %', v_expected_content_count;
  end if;

  for tag_row in
    select distinct misconception.value->>'tag_code' as tag_code
      from jsonb_array_elements(v3_question_pack) question
      cross join lateral jsonb_array_elements(question.value->'misconceptions') misconception(value)
  loop
    insert into public.learning_misconception_tags(code, title, description, active)
    values (tag_row.tag_code, initcap(replace(tag_row.tag_code, '_', ' ')),
      'Sinal autoral de erro recorrente no conteudo TecEscola V3.', true)
    on conflict (code) do update set title = excluded.title, description = excluded.description, active = true;
  end loop;

  for content_row in
    select * from jsonb_to_recordset(v3_question_pack) as item(
      question_id text, subject_code text, target_skill text, domain text,
      topic text, purpose text, cognitive_process text, context_family text,
      difficulty text, statement text, options jsonb, correct_answer text,
      explanation text, secondary_links jsonb, misconceptions jsonb
    )
  loop
    select subject.code as subject_code, subject.name as subject_name,
           skill.id as target_id, skill.domain as target_domain
      into target_row
      from public.learning_canonical_subjects subject
      join public.learning_curriculum_skills skill
        on skill.canonical_subject_id = subject.id
       and skill.code = content_row.target_skill and skill.active
     where subject.code = content_row.subject_code and subject.active;
    if target_row.target_id is null then
      raise exception 'ADAPTIVE_V3_CONTENT_TARGET_MISSING: %', content_row.question_id;
    end if;

    question_metadata := jsonb_build_object(
      'adaptive_v3_purpose', content_row.purpose, 'adaptive_version', 'V3',
      'content_pack', 'tec-escola-core-v3', 'content_question_id', content_row.question_id,
      'context_family', content_row.context_family, 'cognitive_process', content_row.cognitive_process,
      'knowledge_mapping_status', 'READY', 'provenance', 'TECESCOLA_CORE_V3',
      'capability', (select capability from public.learning_canonical_subjects where code = content_row.subject_code),
      'secondary_links', content_row.secondary_links, 'misconceptions', content_row.misconceptions
    );

    select question.id into question_id
      from public.learning_question_bank question
     where question.source_type = 'TECESCOLA_CORE_V3'
       and question.metadata->>'content_question_id' = content_row.question_id limit 1;

    if question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, canonical_subject_id,
        cognitive_process, context_family, knowledge_mapping_status,
        knowledge_mapping_version, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V3', 'TecEscola Core V3', content_row.subject_code,
        content_row.domain, content_row.topic, content_row.statement, content_row.options,
        to_jsonb(content_row.correct_answer), content_row.explanation, content_row.difficulty, 3,
        'Conteudo autoral versionado do TecEscola; nao e BNCC oficial.', question_metadata,
        (select id from public.learning_canonical_subjects where code = content_row.subject_code),
        content_row.cognitive_process, content_row.context_family, 'READY', 'V3', true
      ) returning id into question_id;
    else
      update public.learning_question_bank set
        statement = content_row.statement, options = content_row.options,
        correct_answer = to_jsonb(content_row.correct_answer), explanation = content_row.explanation,
        difficulty = content_row.difficulty, metadata = question_metadata,
        canonical_subject_id = (select id from public.learning_canonical_subjects where code = content_row.subject_code),
        subject_area = content_row.subject_code, domain = content_row.domain, topic = content_row.topic,
        cognitive_process = content_row.cognitive_process, context_family = content_row.context_family,
        knowledge_mapping_status = 'READY', knowledge_mapping_version = 'V3',
        active = true, updated_at = now()
      where id = question_id;
    end if;

    delete from public.learning_question_bank_skill_links where question_bank_id = question_id;
    insert into public.learning_question_bank_skill_links(
      question_bank_id, canonical_skill_id, skill_role, evidence_bearing, attribution_confidence
    ) values (question_id, target_row.target_id, 'PRIMARY', true, 1);

    for mapping_row in
      select * from jsonb_to_recordset(coalesce(content_row.secondary_links, '[]'::jsonb)) as item(
        skill_code text, role text, evidence_bearing boolean, attribution_confidence numeric
      )
    loop
      select skill.id into prerequisite_id from public.learning_curriculum_skills skill
       where skill.catalog_id = v_catalog_id and skill.code = mapping_row.skill_code and skill.active limit 1;
      if prerequisite_id is not null and mapping_row.role in ('SUPPORTING', 'PREREQUISITE', 'TRANSFER') then
        insert into public.learning_question_bank_skill_links(
          question_bank_id, canonical_skill_id, skill_role, evidence_bearing, attribution_confidence
        ) values (question_id, prerequisite_id, mapping_row.role,
                  coalesce(mapping_row.evidence_bearing, false), coalesce(mapping_row.attribution_confidence, .5))
        on conflict (question_bank_id, canonical_skill_id)
        do update set skill_role = excluded.skill_role, evidence_bearing = excluded.evidence_bearing,
          attribution_confidence = excluded.attribution_confidence;
      end if;
    end loop;

    for misconception_row in
      select * from jsonb_to_recordset(coalesce(content_row.misconceptions, '[]'::jsonb)) as item(
        option_value text, tag_code text, confidence_weight numeric, skill_code text
      )
    loop
      select skill.id into prerequisite_id from public.learning_curriculum_skills skill
       where skill.catalog_id = v_catalog_id and skill.code = misconception_row.skill_code and skill.active limit 1;
      insert into public.learning_question_option_misconceptions(
        question_bank_id, option_value, misconception_tag_id, canonical_skill_id, confidence_weight, metadata
      )
      select question_id, misconception_row.option_value, tag.id, prerequisite_id,
             coalesce(misconception_row.confidence_weight, .8),
             jsonb_build_object('provenance', 'TECESCOLA_CORE_V3')
        from public.learning_misconception_tags tag
       where tag.code = misconception_row.tag_code and prerequisite_id is not null
      on conflict do nothing;
    end loop;
  end loop;

  select count(*) into v_materialized_question_count
    from public.learning_question_bank question
   where question.source_type = 'TECESCOLA_CORE_V3'
     and question.active
     and question.metadata->>'content_pack' = 'tec-escola-core-v3';
  if v_materialized_question_count <> v_expected_content_count then
    raise exception 'ADAPTIVE_V3_CONTENT_MATERIALIZATION_INCOMPLETE: expected %, found %',
      v_expected_content_count, v_materialized_question_count;
  end if;

  for target_row in
    select subject.code as subject_code, subject.name as subject_name,
           subject.metadata->>'target_skill' as target_code, skill.id as target_id,
           skill.domain as target_domain
      from public.learning_canonical_subjects subject
      join public.learning_curriculum_skills skill
        on skill.canonical_subject_id = subject.id
       and skill.code = subject.metadata->>'target_skill' and skill.active
     where subject.active
  loop
    for set_purpose in select unnest(array['PROBE','PRACTICE','TRANSFER','LOCK_IN','REVIEW']) loop
      select id into v_question_set_id from public.learning_question_sets question_set
        where question_set.scope = 'GLOBAL' and question_set.canonical_skill_id = target_row.target_id
          and question_set.purpose = set_purpose and question_set.version = 3 limit 1;
      if v_question_set_id is null then
        insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, metadata)
        values ('GLOBAL', target_row.target_id, set_purpose, 3,
          jsonb_build_object('content_pack', 'tec-escola-core-v3', 'adaptive_version', 'V3'))
        returning id into v_question_set_id;
      else
        update public.learning_question_sets set
          metadata = metadata || jsonb_build_object('content_pack', 'tec-escola-core-v3', 'adaptive_version', 'V3'),
          active = true, updated_at = now()
         where id = v_question_set_id;
      end if;
      delete from public.learning_question_set_items item where item.question_set_id = v_question_set_id;
      insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
      select v_question_set_id, question.id, row_number() over (order by question.metadata->>'content_question_id') - 1
        from public.learning_question_bank question
        join public.learning_question_bank_skill_links primary_link
          on primary_link.question_bank_id = question.id
         and primary_link.canonical_skill_id = target_row.target_id
         and primary_link.skill_role = 'PRIMARY'
        where question.source_type = 'TECESCOLA_CORE_V3'
          and question.metadata->>'adaptive_v3_purpose' = set_purpose and question.active;
      select count(*) into v_question_set_item_count
        from public.learning_question_set_items item
       where item.question_set_id = v_question_set_id;
      if v_question_set_item_count = 0 then
        raise exception 'ADAPTIVE_V3_QUESTION_SET_INCOMPLETE: %/% has no active questions',
          target_row.subject_code, set_purpose;
      end if;
    end loop;
  end loop;

  insert into public.learning_skill_relationships(from_canonical_skill_id, to_canonical_skill_id, relation_type, relation_source, confidence, metadata)
  select target.id, ratio.id, 'PREREQUISITE', 'TECESCOLA_DERIVED', .8,
         jsonb_build_object('reason', 'Velocidade media exige divisao e razao.')
    from public.learning_curriculum_skills target
    join public.learning_curriculum_skills ratio on ratio.catalog_id = target.catalog_id and ratio.code = 'RATIO_PROPORTION'
   where target.catalog_id = v_catalog_id and target.code = 'PHYSICS_AVERAGE_SPEED'
  on conflict do nothing;

  insert into public.learning_skill_relationships(from_canonical_skill_id, to_canonical_skill_id, relation_type, relation_source, confidence)
  select percentage.id, ratio.id, 'RELATED', 'TECESCOLA_DERIVED', .7
    from public.learning_curriculum_skills percentage
    join public.learning_curriculum_skills ratio on ratio.catalog_id = percentage.catalog_id and ratio.code = 'RATIO_PROPORTION'
   where percentage.catalog_id = v_catalog_id and percentage.code = 'PERCENTAGE'
   on conflict do nothing;

end;
$seed$;

-- Keep an empty newer set from shadowing a usable fallback set in the V2 flow.
create or replace function private.pick_learning_question_set_v2(
  target_institution_id uuid,
  target_teacher_profile_id uuid,
  target_skill_id uuid,
  target_purpose text
)
returns uuid language sql stable security definer set search_path = ''
as $$
  select set_row.id
    from public.learning_question_sets set_row
   where set_row.canonical_skill_id = target_skill_id
     and set_row.purpose = target_purpose
     and set_row.active
     and exists (
       select 1
         from public.learning_question_set_items item
         join public.learning_question_bank bank on bank.id = item.question_bank_id and bank.active
        where item.question_set_id = set_row.id
     )
     and (
       (set_row.scope = 'TEACHER' and set_row.institution_id = target_institution_id and set_row.teacher_profile_id = target_teacher_profile_id)
       or (set_row.scope = 'INSTITUTION' and set_row.institution_id = target_institution_id)
       or (set_row.scope = 'GLOBAL' and set_row.institution_id is null)
     )
   order by case set_row.scope when 'TEACHER' then 0 when 'INSTITUTION' then 1 else 2 end,
            set_row.version desc, set_row.id
   limit 1;
$$;

create or replace function private.enforce_learning_v3_capability_gate()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare subject_capability text;
begin
  select subject.capability into subject_capability
    from public.learning_curriculum_skills skill
    join public.learning_canonical_subjects subject on subject.id = skill.canonical_subject_id
   where skill.id = new.canonical_skill_id;
  if new.state = 'MASTERED'
     and subject_capability in ('CONSTRUCTED_EVIDENCE_REQUIRED', 'OBSERVATIONAL_EVIDENCE_REQUIRED') then
    new.state := 'PRACTICING';
  end if;
  return new;
end;
$$;
drop trigger if exists learning_student_skill_state_v3_capability_gate on public.learning_student_skill_state;
create trigger learning_student_skill_state_v3_capability_gate
before insert or update of state on public.learning_student_skill_state
for each row execute function private.enforce_learning_v3_capability_gate();

create or replace function private.learning_question_bank_v3_ready(target_question_id uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.learning_question_bank question
    where question.id = target_question_id
      and question.active
      and question.knowledge_mapping_status = 'READY'
      and question.knowledge_mapping_version = 'V3'
      and question.subject_area is not null
      and question.domain is not null
      and question.topic is not null
      and question.cognitive_process is not null
      and question.provenance is not null
      and question.statement not ilike '%qual alternativa aplica melhor o conceito ao contexto apresentado%'
      and question.options::text not ilike '%Aplicacao coerente de%'
      and (select count(*) from public.learning_question_bank_skill_links link where link.question_bank_id = question.id and link.skill_role = 'PRIMARY') = 1
  );
$$;

create or replace function private.validate_learning_question_set_item_v3()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare set_metadata jsonb;
begin
  select metadata into set_metadata from public.learning_question_sets where id = new.question_set_id;
  if coalesce(set_metadata->>'adaptive_version', '') = 'V3'
     and not private.learning_question_bank_v3_ready(new.question_bank_id) then
    raise exception 'ADAPTIVE_SET_WITH_UNMAPPED_QUESTION';
  end if;
  return new;
end;
$$;
drop trigger if exists learning_question_set_items_validate_v3 on public.learning_question_set_items;
create trigger learning_question_set_items_validate_v3
before insert or update on public.learning_question_set_items
for each row execute function private.validate_learning_question_set_item_v3();

create or replace function public.validate_learning_question_set_v3(p_question_set_id uuid)
returns jsonb language plpgsql stable security definer set search_path = ''
as $$
declare total_count integer; invalid_count integer;
begin
  select count(*)::integer into total_count from public.learning_question_set_items where question_set_id = p_question_set_id;
  select count(*)::integer into invalid_count from public.learning_question_set_items item where item.question_set_id = p_question_set_id and not private.learning_question_bank_v3_ready(item.question_bank_id);
  return jsonb_build_object('question_set_id', p_question_set_id, 'total_questions', total_count, 'invalid_questions', invalid_count, 'publishable', total_count > 0 and invalid_count = 0);
end;
$$;

create or replace function private.refresh_learning_misconception_signal_v3(
  target_institution_id uuid,
  target_student_id uuid,
  target_skill_id uuid,
  target_tag_id uuid
)
returns void language plpgsql security definer set search_path = ''
as $$
declare negative_count integer; context_count integer; positive_count integer; signal_state text; confidence numeric;
begin
  select count(*) filter (where not correct)::integer,
         count(distinct context_family) filter (where not correct)::integer,
         count(*) filter (where correct)::integer
    into negative_count, context_count, positive_count
    from public.learning_evidence_attributions
   where institution_id = target_institution_id and student_id = target_student_id
     and canonical_skill_id = target_skill_id and misconception_tag_id = target_tag_id;
  signal_state := case
    when negative_count >= 3 and context_count >= 2 and positive_count >= 2 then 'RESOLVED'
    when negative_count >= 3 and context_count >= 2 and positive_count = 1 then 'RECOVERING'
    when negative_count >= 3 and context_count >= 2 then 'CONFIRMED'
    when negative_count = 2 then 'SUSPECTED'
    when negative_count = 1 then 'SIGNAL'
    else 'RESOLVED'
  end;
  confidence := least(1::numeric, (negative_count::numeric / 3) * .6 + (context_count::numeric / 2) * .4);
  insert into public.learning_misconception_signals(
    institution_id, student_id, canonical_skill_id, misconception_tag_id, state,
    signal_count, distinct_context_count, recovery_count, confidence,
    first_signal_at, last_signal_at, last_recovery_at, updated_at
  ) values (
    target_institution_id, target_student_id, target_skill_id, target_tag_id, signal_state,
    negative_count, context_count, positive_count, confidence,
    now(), now(), case when positive_count > 0 then now() else null end, now()
  ) on conflict (institution_id, student_id, canonical_skill_id, misconception_tag_id)
  do update set state = excluded.state, signal_count = excluded.signal_count,
    distinct_context_count = excluded.distinct_context_count, recovery_count = excluded.recovery_count,
    confidence = excluded.confidence, last_signal_at = now(),
    last_recovery_at = case when excluded.recovery_count > 0 then now() else learning_misconception_signals.last_recovery_at end,
    updated_at = now();
end;
$$;

create or replace function private.record_learning_v3_attributions()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare answer_item jsonb; question_id uuid; selected_option text; expected_option text; is_correct boolean; context text; link record; tag record; has_tag boolean;
begin
  for answer_item in select value from jsonb_array_elements(coalesce(new.answers, '[]'::jsonb)) value loop
    begin question_id := (answer_item->>'question_bank_id')::uuid; exception when others then question_id := null; end;
    if question_id is null then continue; end if;
    selected_option := answer_item->'answer' #>> '{}';
    select question.correct_answer #>> '{}', question.context_family into expected_option, context
      from public.learning_question_bank question where question.id = question_id;
    is_correct := selected_option is not distinct from expected_option;
    has_tag := false;
    for tag in
      select mapping.misconception_tag_id, mapping.canonical_skill_id, mapping.confidence_weight
        from public.learning_question_option_misconceptions mapping
       where mapping.question_bank_id = question_id and mapping.option_value = selected_option
    loop
      has_tag := true;
      for link in
        select skill_link.canonical_skill_id, skill_link.skill_role, skill_link.evidence_bearing, skill_link.attribution_confidence
          from public.learning_question_bank_skill_links skill_link
         where skill_link.question_bank_id = question_id
           and (skill_link.skill_role = 'PRIMARY' or (not is_correct and skill_link.canonical_skill_id = tag.canonical_skill_id) or (is_correct and skill_link.evidence_bearing))
      loop
        insert into public.learning_evidence_attributions(
          institution_id, student_id, question_bank_id, guided_attempt_id, canonical_skill_id,
          evidence_role, correct, score, attribution_confidence, misconception_tag_id,
          purpose, context_family, decision_reason_code
        ) values (
          new.institution_id, new.student_id, question_id, new.id, link.canonical_skill_id,
          link.skill_role, is_correct, case when is_correct then 100 else 0 end,
          case when not is_correct and link.skill_role <> 'PRIMARY' then tag.confidence_weight else link.attribution_confidence end,
          case when not is_correct then tag.misconception_tag_id else null end,
          new.purpose, context,
          case when is_correct and link.skill_role = 'SUPPORTING' then 'SUPPORT_SKILL_POSITIVE_EVIDENCE' when not is_correct and link.skill_role = 'PRIMARY' then 'PRIMARY_SKILL_LOW_EVIDENCE' else 'MISCONCEPTION_REPEATED' end
        ) on conflict do nothing;
        if not is_correct then perform private.refresh_learning_misconception_signal_v3(new.institution_id, new.student_id, tag.canonical_skill_id, tag.misconception_tag_id); end if;
      end loop;
    end loop;
    if not has_tag then
      for link in
        select skill_link.canonical_skill_id, skill_link.skill_role, skill_link.attribution_confidence
          from public.learning_question_bank_skill_links skill_link
         where skill_link.question_bank_id = question_id
           and (skill_link.skill_role = 'PRIMARY' or (is_correct and skill_link.evidence_bearing))
      loop
        insert into public.learning_evidence_attributions(
          institution_id, student_id, question_bank_id, guided_attempt_id, canonical_skill_id,
          evidence_role, correct, score, attribution_confidence, purpose, context_family, decision_reason_code
        ) values (
          new.institution_id, new.student_id, question_id, new.id, link.canonical_skill_id,
          link.skill_role, is_correct, case when is_correct then 100 else 0 end,
          link.attribution_confidence, new.purpose, context,
          case when is_correct then 'PRIMARY_SKILL_EVIDENCE' else 'PRIMARY_SKILL_LOW_EVIDENCE' end
        ) on conflict do nothing;
      end loop;
    end if;
  end loop;
  return new;
end;
$$;
drop trigger if exists learning_guided_step_attempts_record_v3_attribution on public.learning_guided_step_attempts;
create trigger learning_guided_step_attempts_record_v3_attribution
after insert on public.learning_guided_step_attempts
for each row execute function private.record_learning_v3_attributions();

create or replace function private.learning_v3_can_view_student(target_institution_id uuid, target_student_id uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.students student where student.id = target_student_id and student.institution_id = target_institution_id and student.active and student.profile_id = auth.uid())
      or public.can_manage_institution_operations(target_institution_id)
      or exists (
        select 1 from public.enrollments enrollment
        join public.subject_offerings offering on offering.class_id = enrollment.class_id and offering.active
        join public.classes school_class on school_class.id = offering.class_id and school_class.institution_id = target_institution_id
        where enrollment.student_id = target_student_id and enrollment.active
          and offering.teacher_profile_id = auth.uid()
      );
$$;

create or replace function public.get_student_knowledge_graph_v3(p_institution_id uuid, p_student_id uuid)
returns jsonb language plpgsql stable security definer set search_path = ''
as $$
begin
  if not private.learning_v3_can_view_student(p_institution_id, p_student_id) then raise exception 'LEARNING_KNOWLEDGE_GRAPH_SCOPE_DENIED'; end if;
  return jsonb_build_object(
    'student_id', p_student_id,
    'skills', coalesce((select jsonb_agg(jsonb_build_object(
      'subject', subject.code, 'subject_name', subject.name, 'skill', skill.code,
      'skill_title', skill.title, 'state', coalesce(state.state, 'UNKNOWN'),
      'mastery', coalesce(state.mastery_estimate, 0), 'confidence', coalesce(state.confidence, 0),
      'evidence_count', coalesce(state.evidence_count, 0), 'strong_evidence_count', coalesce(state.strong_evidence_count, 0),
      'last_evidence_at', state.last_evidence_at,
      'confirmed_misconceptions', coalesce((select jsonb_agg(jsonb_build_object('code', tag.code, 'state', signal.state, 'confidence', signal.confidence)) from public.learning_misconception_signals signal join public.learning_misconception_tags tag on tag.id = signal.misconception_tag_id where signal.institution_id = p_institution_id and signal.student_id = p_student_id and signal.canonical_skill_id = skill.id and signal.state in ('CONFIRMED','RECOVERING')), '[]'::jsonb)
    ) order by subject.code, skill.code)
      from public.learning_curriculum_skills skill
      join public.learning_canonical_subjects subject on subject.id = skill.canonical_subject_id and subject.active
      left join public.learning_student_skill_state state on state.institution_id = p_institution_id and state.student_id = p_student_id and state.canonical_skill_id = skill.id
     where skill.active), '[]'::jsonb)
  );
end;
$$;

create or replace function public.get_teacher_student_knowledge_graph_v3(p_institution_id uuid, p_student_id uuid)
returns jsonb language sql stable security definer set search_path = ''
as $$
  select public.get_student_knowledge_graph_v3(p_institution_id, p_student_id);
$$;

create or replace function public.get_teacher_class_knowledge_heatmap_v3(p_institution_id uuid, p_class_id uuid)
returns table(subject_code text, skill_code text, mastered_count integer, practicing_count integer, needs_review_count integer, unknown_count integer)
language sql stable security definer set search_path = ''
as $$
  select subject.code, skill.code,
    count(*) filter (where state.state = 'MASTERED')::integer,
    count(*) filter (where state.state in ('INTRODUCED','PRACTICING'))::integer,
    count(*) filter (where state.state = 'NEEDS_REVIEW')::integer,
    count(*) filter (where state.state is null or state.state = 'UNKNOWN')::integer
  from public.enrollments enrollment
  join public.students student on student.id = enrollment.student_id and student.institution_id = p_institution_id and student.active
  cross join public.learning_curriculum_skills skill
  join public.learning_canonical_subjects subject on subject.id = skill.canonical_subject_id and subject.active
  left join public.learning_student_skill_state state on state.institution_id = p_institution_id and state.student_id = student.id and state.canonical_skill_id = skill.id
  where enrollment.class_id = p_class_id and enrollment.active
    and (public.can_manage_institution_operations(p_institution_id) or exists (select 1 from public.subject_offerings offering join public.classes school_class on school_class.id = offering.class_id and school_class.institution_id = p_institution_id where offering.class_id = p_class_id and offering.teacher_profile_id = auth.uid() and offering.active))
    and skill.active
  group by subject.code, skill.code
  order by subject.code, skill.code;
$$;

create or replace function public.get_adaptive_v3_plan(p_institution_id uuid, p_student_id uuid, p_target_canonical_skill_id uuid)
returns jsonb language plpgsql stable security definer set search_path = ''
as $$
declare target_skill public.learning_curriculum_skills%rowtype; target_subject public.learning_canonical_subjects%rowtype; bridge record; current_subject text; current_skill text; decision text; reason text;
begin
  if not private.learning_v3_can_view_student(p_institution_id, p_student_id) then raise exception 'LEARNING_KNOWLEDGE_GRAPH_SCOPE_DENIED'; end if;
  select * into target_skill from public.learning_curriculum_skills where id = p_target_canonical_skill_id and active;
  if not found then raise exception 'LEARNING_TARGET_NOT_FOUND'; end if;
  select * into target_subject from public.learning_canonical_subjects where id = target_skill.canonical_subject_id;
  select relation.to_canonical_skill_id, bridge_skill.code, bridge_subject.code as subject_code into bridge
    from public.learning_skill_relationships relation
    join public.learning_curriculum_skills bridge_skill on bridge_skill.id = relation.to_canonical_skill_id
    join public.learning_canonical_subjects bridge_subject on bridge_subject.id = bridge_skill.canonical_subject_id
    join public.learning_misconception_signals signal on signal.institution_id = p_institution_id and signal.student_id = p_student_id and signal.canonical_skill_id = relation.to_canonical_skill_id and signal.state = 'CONFIRMED'
   where relation.from_canonical_skill_id = p_target_canonical_skill_id and relation.relation_type in ('PREREQUISITE','RELATED','TRANSFER')
   order by signal.confidence desc, bridge_skill.code
   limit 1;
  if bridge.code is not null then
    decision := 'CROSS_SUBJECT_BRIDGE'; reason := 'PREREQUISITE_CONFIRMED_GAP'; current_skill := bridge.code; current_subject := bridge.subject_code;
  else
    select state into current_skill from public.learning_student_skill_state where institution_id = p_institution_id and student_id = p_student_id and canonical_skill_id = p_target_canonical_skill_id;
    if current_skill is null then decision := 'DIAGNOSTIC_NEEDED'; reason := 'PRIMARY_SKILL_LOW_EVIDENCE'; else decision := 'RETURN_TO_ORIGINAL_TARGET'; reason := 'RETURN_TO_ORIGINAL_TARGET'; end if;
    current_skill := target_skill.code; current_subject := target_subject.code;
  end if;
  return jsonb_build_object('decision', decision, 'reason_code', reason, 'original_target_subject', target_subject.code, 'original_target_skill', target_skill.code, 'current_subject', current_subject, 'current_skill', current_skill);
end;
$$;

create or replace function public.replan_guided_learning_session_v3(p_session_id uuid)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare session_row public.learning_guided_sessions%rowtype; plan jsonb;
begin
  select * into session_row from public.learning_guided_sessions where id = p_session_id for update;
  if not found or not private.learning_v2_scope_student(session_row.institution_id, session_row.student_id) then raise exception 'LEARNING_SESSION_SCOPE_DENIED'; end if;
  plan := public.get_adaptive_v3_plan(session_row.institution_id, session_row.student_id, session_row.original_target_canonical_skill_id);
  update public.learning_guided_sessions set planner_version = 'V3', current_canonical_skill_id = (select id from public.learning_curriculum_skills where code = plan->>'current_skill' and active limit 1), current_canonical_subject_id = (select id from public.learning_canonical_subjects where code = plan->>'current_subject' and active limit 1), decision_reason = plan->>'reason_code', metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('adaptive_v3_plan', plan, 'original_target_preserved', true), updated_at = now() where id = p_session_id;
  return plan;
end;
$$;

update public.learning_guided_sessions session
   set original_target_canonical_subject_id = skill.canonical_subject_id,
       current_canonical_subject_id = skill.canonical_subject_id
  from public.learning_curriculum_skills skill
 where session.target_canonical_skill_id = skill.id
   and (session.original_target_canonical_subject_id is null or session.current_canonical_subject_id is null);

alter table public.learning_canonical_subjects enable row level security;
alter table public.learning_skill_relationships enable row level security;
alter table public.learning_question_option_misconceptions enable row level security;
alter table public.learning_evidence_attributions enable row level security;
alter table public.learning_misconception_signals enable row level security;

drop policy if exists learning_canonical_subjects_select on public.learning_canonical_subjects;
create policy learning_canonical_subjects_select on public.learning_canonical_subjects for select to authenticated using (active);
drop policy if exists learning_skill_relationships_select on public.learning_skill_relationships;
create policy learning_skill_relationships_select on public.learning_skill_relationships for select to authenticated using (true);
drop policy if exists learning_evidence_attributions_select on public.learning_evidence_attributions;
create policy learning_evidence_attributions_select on public.learning_evidence_attributions for select to authenticated using (private.learning_v3_can_view_student(institution_id, student_id));
drop policy if exists learning_misconception_signals_select on public.learning_misconception_signals;
create policy learning_misconception_signals_select on public.learning_misconception_signals for select to authenticated using (private.learning_v3_can_view_student(institution_id, student_id));

revoke all on table public.learning_question_option_misconceptions from anon, authenticated;
grant all on table public.learning_question_option_misconceptions to service_role;
grant select on table public.learning_canonical_subjects, public.learning_skill_relationships to authenticated;
grant select on table public.learning_evidence_attributions, public.learning_misconception_signals to authenticated;
grant all on table public.learning_canonical_subjects, public.learning_skill_relationships, public.learning_evidence_attributions, public.learning_misconception_signals to service_role;
grant execute on function public.validate_learning_question_set_v3(uuid), public.get_student_knowledge_graph_v3(uuid, uuid), public.get_teacher_student_knowledge_graph_v3(uuid, uuid), public.get_teacher_class_knowledge_heatmap_v3(uuid, uuid), public.get_adaptive_v3_plan(uuid, uuid, uuid), public.replan_guided_learning_session_v3(uuid) to authenticated;

revoke all on function private.learning_question_bank_v3_ready(uuid), private.validate_learning_question_set_item_v3(), private.refresh_learning_misconception_signal_v3(uuid, uuid, uuid, uuid), private.record_learning_v3_attributions(), private.learning_v3_can_view_student(uuid, uuid), private.enforce_learning_v3_capability_gate() from public, anon, authenticated;

commit;
